window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26828557"]={"book":{"id":26828557,"title":"从行动开始","author":"[日]石田淳","translator":"朱悦玮","publisher":"后浪出版公司·江西人民出版社","pubdate":"2016-9","isbn":"9787210085799","tags":["自我管理","个人管理","自我成长","行为学","心理学","管理","行为","心理"],"memCount":17},"np":1,"pb":[19],"idx":[{"i":19507,"t":"控制情绪的方法","l":"TF1-2","c":"可乐","g":1,"p":1},{"i":9599,"t":"从小行动开始","l":"TF2-4","c":"小鱼-","g":1,"p":1},{"i":7501,"t":"利用“正念法”纠正“认知偏差”","l":"TF1-1","c":"RIA何孔明","g":1,"p":1},{"i":6472,"t":"情绪控制----嗲嗲","l":"TF2-2","c":"嗲嗲~","g":1,"p":1},{"i":4831,"t":"不要轻易否定自己，提升自我效能感","l":"TF1-1","c":"西瓜糖","g":1,"p":1},{"i":3586,"t":"新行动从“三”开始","l":"TF2-1","c":"李瑾","g":1,"p":1},{"i":3522,"t":"拆解《从行动开始》","l":"TF1-2","c":"郑珊珊","g":0,"p":1},{"i":3421,"t":"轻松开始新行动","l":"TF2-1","c":"李瑾","g":0,"p":1},{"i":3339,"t":"《从行动开始》之战胜诱惑","l":"TF2-2","c":"李瑾","g":0,"p":1},{"i":2758,"t":"如何跳出恶性负面情绪","l":"TF1-1","c":"shuangdengmm","g":1,"p":1},{"i":2735,"t":"学会如何战胜诱惑，专注目标","l":"TF2-2","c":"李瑾","g":0,"p":1},{"i":2695,"t":"学会如何培养新行动","l":"TF2-1","c":"李瑾","g":0,"p":1},{"i":2662,"t":"让每天的压力和行动可视化","l":"TF1-2","c":"林德鸿","g":0,"p":1},{"i":1995,"t":"小而具体行动是一切解决问题的开始","l":"TF1-1","c":"张馨月","g":0,"p":1},{"i":1365,"t":"如何让行动持续下去？","l":"TF1-2","c":"徐佳敏","g":1,"p":1},{"i":1363,"t":"如何更好地规划我们的行动","l":"TF2-2","c":"徐佳敏","g":1,"p":1},{"i":1181,"t":"看清沉没成本，敢于面对失败","l":"TF2-1","c":"徐佳敏","g":1,"p":1},{"i":949,"t":"化整为零，把大任务干掉。","l":"TF1-1","c":"徐佳敏","g":0,"p":1},{"i":948,"t":"正视事实，摆脱认知偏差。","l":"TF1-1","c":"徐佳敏","g":0,"p":1}],"ms":[{"id":19507,"topic":"控制情绪的方法","learn_goal":"","remark":"无","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"可乐","city":"银川市"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>请问观察家老师拿到观察家记录表、晋级准备表了吗？\u003c/p>\u003cp>请问现场的小伙伴都准备好了吗？\u003c/p>\u003cp>好，现在正式开始今天的拆解！\u003c/p>\u003cp>自我介绍：1分钟\u003c/p>\u003cp>先跟大家做个自我介绍，用三个标签概括：\u003c/p>\u003cp>1. 我叫张洁；\u003c/p>\u003cp>2. 深耕幼教领域27年的一线教育与管理实践者，帮助过几十位教师成长为骨干教师，曾获贺兰县优秀教师称号；\u003c/p>\u003cp>3. 能为幼教机构提供课程设计、教师及家长培训，也能为家长提供科学育儿指导与幼小衔接规划。\u003c/p>","ratings_count":1,"texts":[{"id":23895,"quote":"\u003cp>每个人都有自己心目中的理想状态。谁也不愿意让别人看到自己气急败坏的样子，而更希望在他人面前展现自己成熟稳重的形象。所以，当一个人情绪激动的时候，也会对自己的愤怒感到不满，从而更加无法控制自己的感情。但他们其实在想：“快来一个人熄灭我的怒火吧！”也就是说，一个陷入冲动状态的人，其实是他的心擅自离开了原本的地方而四处横冲直撞。这就导致他脱离了现实。\u003c/p>\u003cp>接下来我为大家介绍三个帮助控制情绪的简单方法。 \u003c/p>\u003cp>\u003cstrong>方法一：\u003c/strong>对于那些很容易冲动的人，应该先忍耐 30 秒。当你想要怒吼着爆发之前，只要忍耐短短 30 秒，那么事情将会变得完全不同。A 先生就是因为没有等待 30 秒就让感情肆意宣泄出来了。如果一个人连 30 秒都无法忍耐，那是因为他还没有习惯这种行为方式。\u003c/p>\u003cp>\u003cstrong>方法二：\u003c/strong>紧紧握住右手当你感到焦躁不安的时候，可以紧紧地握住右手。只需要这样一个动作就能奏效。这就像暗示自己“不要冲动，保持冷静”一样。当你被突然袭来的负面情绪所笼罩时，这样做可以使你不至于情绪失控，重新回到现实中来。如果习惯握左手也可以。\u003c/p>\u003cp>\u003cstrong>方法三\u003c/strong>：数呼吸\u003c/p>\u003cp>在椅子上找一个舒服的姿势坐下，让身体彻底放松，缓缓地进行腹式呼吸。每次呼吸都数数，一直数到 10。\u003c/p>\u003cp>这是非常简单的动作，所以在做的过程中头脑里可能会浮现出杂念，但不必担心受杂念影响而数错，如果真的忘记了数到几，请从头再来一遍。数自己呼吸的次数，就算浮现出杂念也不必在意。通过重复这种简单的行动就可以使你的身心恢复平静，让你的注意力再次回到现实。之所以推荐腹式呼吸而不是胸式呼吸，是因为腹式呼吸能调动副交感神经，产生放松的效果。\u003c/p>","explains":"\u003cp>\u003cstrong>一、What（是什么：一套超实用的情绪急救方案）\u003c/strong>\u003c/p>\u003cp>大家好！今天要分享的，是一套能快速搞定冲动、不安、嫉妒等负面情绪的“急救方法”。核心特别简单，就是“30秒忍耐+两个小动作”，不用复杂技巧，人人都能上手，专门解决情绪上来时“管不住嘴、控不住火”的问题。\u003c/p>\u003cp>\u003cstrong>二、Why（为什么：我们为啥需要这套方法？）\u003c/strong>\u003c/p>\u003cp>我想没人愿意让别人看到自己乱发脾气、气急败坏的模样。但有意思的是，越想控制愤怒，往往越容易失控，甚至会因为“自己怎么又发火了”而更自责，陷入恶性循环。所以这套方法，本质就是帮我们把“跑丢的心”拉回现实，避免因一时冲动出错。\u003c/p>\u003cp>\u003cstrong>三、where（适用于那些场景）\u003c/strong>\u003c/p>\u003cp>容易冲动的“易燃体质”人群，一遇到不顺心就想发火、忍不住吐槽；其次是经常感到不安、焦虑，或者看到别人优秀就容易嫉妒的人；甚至是偶尔会情绪“掉线”，事后总后悔“当时怎么没忍住”的朋友，这套方法都能帮上忙，堪称“全民通用的情绪维稳神器”。\u003c/p>\u003cp>四、How（怎么做：3个方法就能搞定，简单到离谱！）\u003c/p>\u003cp>1.\u003cstrong> 方法一：\u003c/strong>遇到事情先停30秒：当你想怒吼、想爆发的瞬间，先让自己停下来，忍耐短短30秒。别觉得30秒长，就喝口水、眨眨眼的功夫，却能让情绪从“峰值”降下来，避免像A先生那样后悔。如果一开始忍不住，没关系，多练几次就会习惯。\u003c/p>\u003cp>2. \u003cstrong>方法二：\u003c/strong>握紧双手（左手右手都可以）。感到焦躁不安时，紧紧攥住自己的手，这个动作就像在给大脑发信号：“冷静！别冲动！” 不用费力气，一个小动作就能帮你从负面情绪里拉回来，重新聚焦现实。\u003c/p>\u003cp>3.\u003cstrong>方法三：\u003c/strong>腹式呼吸数到10。找个舒服的姿势坐下，让身体放松，然后慢慢做腹式呼吸——吸气时肚子鼓起来，呼气时肚子收回去，每呼吸一次数一个数，从1数到10。过程中走神、数错都没关系，忘了就从头数，不用纠结。之所以选腹式呼吸，是因为它能调动身体的副交感神经，快速产生放松效果，比普通的胸式呼吸管用多了。\u003c/p>\u003cp>话术：看完拆页的内容，我立即联想到发生在我和老公之间的一个故事：\u003c/p>\u003cp>刚进门，就被飞来一个白眼，紧接着就是机关枪一样的责备：“打电话永远不接，手机永远就是摆设，是烧火棍子？还想换手机，换个屁！”\u003c/p>\u003cp>听到这里我的气不打一处来，一百个想法从我脑子里冒出来，毫不客气地堵了回去：“我从来不做饭，好不容易给你做饭，抽油烟机开着听不见手机响多正常，发什么神经病！自己做去，我不吃了！” 气呼呼地扔了围裙，回了卧室。\u003c/p>\u003cp>如果当初我掌握了这三个“情绪急救锦囊”，我想当时我的心态、处理方式以及最终结果，一定会不一样。\u003c/p>","interaction":"\u003cp>1.我们了解了这个拆页，也知道了在情绪上头时可以用“三个冷静法”，现在请大家回想一下：自己有没有过类似的经历？请在大组内自由分享，每人1~2分钟，总共给大家4分钟讨论时间；\u003c/p>\u003cp>2.讨论结束后，我们邀请1~2位小伙伴分享自己的故事；\u003c/p>\u003cp>3.学习者案例记录：（现场记录分享者核心经历）\u003c/p>\u003cp>4.反馈：好，非常感谢这位小伙伴的真诚分享！你的经历让我们更清楚，情绪失控时真的需要一套简单直接的方法来“救场”，而我们今天学的内容，正好能解决这个问题。\u003c/p>\u003cp>\u003cstrong>（拆书家提问设计）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家引导语：\u003c/strong>听完大家的分享，相信大家都能感受到这套“情绪急救法”的实用价值。\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>未来一周当大家遇到触发你情绪的时刻，孩子吃饭磨蹭等情况，至少两次用握手或者腹式呼吸法调整情绪。现在——给大家2分钟时间，在我准备的模板里写下自己的应用规划；\u003c/p>\u003cp>1.写完的小伙伴请举手示意我，之后我们邀请几位小伙伴分享自己的规划；\u003c/p>\u003cp>2.学习者案例记录：（现场记录分享者核心规划）\u003c/p>\u003cp>3.感谢小伙伴的分享！把目标写下来，能让我们的行动更有方向。希望大家在接下来的一周里，主动运用今天学的方法，让情绪可控，让每一次沟通都更顺畅。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1765156663000,"updated_at":1765781700000,"ria":true},{"id":9599,"topic":"从小行动开始","learn_goal":"设定目标后，从小行动开始，积累成就感持续行动，促进目标实现","remark":"《从行动开始》这本书他的作者是石田淳。作者想让读者认识到，当你想要实现某种目标的时候，需要的不是干劲和认真的态度，而是切实的行动。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"小鱼-","city":"沈阳市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>TF2-4学习主题\u003c/strong>:&nbsp;从微小的行动开始改变\u003c/p>\u003cp>\u003cstrong>学习目标:\u003c/strong>&nbsp;学习者在设定目标后，将注意力放在行动上，能够从小行动开始目标的实施，促进目标的达成。\u003c/p>\u003cp>\u003cstrong>开场：\u003c/strong>\u003c/p>\u003cp>如果有人说，只要你的意志力足够强，你就可以像姚明一样高，那你肯定觉得他疯了。但如果他说，只要你意志力足够强，你就可以学会一门语言，学习一项技能，你就会想，哎有可能啊。我们那些折掉的目标，没达成的愿望，没培养出来的好习惯，是意志力不够？规划不到位？性格问题？忘掉那些想法！当你设定目标后，需要的不是干劲和认真的态度，而是切实的行动。大家好，我是小鱼。陪伴赋能，持续精进。欢迎大家来拆书。今天么我们一起来学习两种从小行动入手的方法开启新行动。过会儿的学习中，我们会有小组讨论，我们先分一下组，左手边的伙伴一组，右手边的伙伴一组，和身边的伙伴确认一下眼神吧！\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>（1-2分钟）我先为大家介绍一下今天的书籍《从行动开始》\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>\u003cstrong>特征\u003c/strong>：\u003c/p>\u003cp>《从行动开始》这本书他的作者是石田淳。他是日本研究行为科学管理的第一人。这个方法获得包括美国太空总署和波音公司在内的600多家公司采用，在美国企业创造出绝佳成绩。《从行动开始》这本书想告诉我们是：当你想要实现某种目标的时候，需要的不是干劲和认真的态度，而是切实的行动。\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>\u003cstrong>优势：\u003c/strong>这本书是自我管理类书籍，书中完整的介绍了“行为科学管理法”。与其他同类书籍相比，更注重行动给人来带的改变。因其具有不依赖意志和个人能力的特性，可推广度高，所以受到关注。\u003c/p>\u003cp>\u003cstrong>B利益：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1:\u003c/strong>当你无法实现自己的愿望的时候，可能会认为自己意志薄弱、没有毅力、性格问题等，我们可以停止这样的想法，从具体的微小的行动开始。这本书启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，学会不抱怨不盲从，灵活有效的规划自己的生活。\u003c/p>\u003cp>\u003cstrong>B2:\u003c/strong>我们今天学习的重点放在在确定某项行动时，运用具体微小的行动开始。明明下定决心要坚持到底，结果却还是半途而废，问题的关键是：你要改变自己的行动方式。今天我们学习的两个拆页会带给我们具体开始行动的方法，轻松开启行动的大门，感受到我能做到，持续行动，达成目标。\u003c/p>\u003cp>下面进入我们的第一个拆页，请大家阅读原文拆页，时间2分钟，大家读完后示意我。\u003c/p>","ratings_count":1,"texts":[{"id":13434,"quote":"\u003cp>\u003cstrong>原文片段一：（10-15分钟）\u003c/strong>\u003c/p>\u003cp>我很喜欢跑步，曾经完成过100千米马拉松和被称为“世界上最残酷”的撒哈拉马拉松。\u003c/p>\u003cp>但实际上，我以前并没有运动的习惯。以前的我身上有很多赘肉，就连上楼梯都会上气不接下气。忽然有一天，我冒出了“跑马拉松”的想法。没错，我想要改变自己。\u003c/p>\u003cp>但那时候我已经40多岁了，坦白地说我并不知道自己是否能做到，就连我身边的人也大多都劝我说“不要折腾了”。于是我去找一位运动专家商量，得到的答案是“我可以”，而这位运动专家给我的建议正是“从小行动开始”。\u003c/p>\u003cp>“首先每周运动两次，每次走30分钟。”当时我可以说是做好了艰苦训练的心理准备，所以当听到这句话时第一反应是“哎，这样就可以吗？”不过，当我按照要求坚持了一段时间之后，就得到了增加运动量的指示。\u003c/p>\u003cp>“在走30分钟的时候试着跑5分钟。”当我能够做到这点之后，跑步的时间就逐渐延长到10分钟、15分钟，最后30分钟。\u003c/p>\u003cp>“我能够坚持跑步30分钟啦！”\u003c/p>\u003cp>对于完全没有运动习惯的我来说，这时候的成就感简直难以用语言来形容。在成就感的驱动下，我又相继完成了10千米马拉松，半程马拉松，最后是全程马拉松。这个成功的经历又激励我完成了100千米马拉松和撒哈拉马拉松。\u003c/p>\u003cp>当然，如果我一开始的目标就是跑完撒哈拉马拉松的话，那我绝对是坚持不下来的。我肯定会在运动过程中遇到挫折，最后只留下不好的回忆。我的改变是通过不断积累小的行动来实现的。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解指导：（\u003c/strong>\u003cstrong>5分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003cstrong>一：\u003c/strong>希望学完这个拆页后，我们在开始做的阶段，能够运用“时间5开始”的小行动，体会到“我做到了”的成就感，增加时间持续行动。\u003c/p>\u003cp>(WHAT)作者通过分享自己是如何完成100千米的撒哈拉马拉松的故事，向我们说明了，(WHERE)在设定一个行动目标后，开始实施行动的阶段，(WHY)我们通常会想让自己一开始就达到成功后的状态，事情并不是一蹴而就，而是循序渐进，时间的因素也是突破行动的关键一步，在开始的时候先来上5分钟，体会到我做到了的成就感，逐渐延长时间，达成目标。(HOW)怎么在开始实施行动中运用“时间5开始”这个行动方法促进目标达成呢？\u003c/p>\u003cp>\u003cstrong>给出更贴近实际的例子：\u003c/strong>\u003cstrong>意译原书案例：\u003c/strong>我很喜欢阅读，一直保持每天晨读的习惯。我以前不太早起，也没有阅读的习惯，鬼使神差我为自己设定了一个目标“坚持一年每天早起晨读1小时”的想法，我并不知道自己是否能做到，于是我去找一位有良好阅读习惯的朋友商量，得到的答案是“我可以”，而这位朋友给我的建议是“从小行动开始”。\u003c/p>\u003cp>“首先每周早起两次，比平时早起30分钟。”只是早起？不读书么？当我按照要求坚持了一段时间之后，就得到了增加阅读时间指示。“在早起30分钟的时候试着阅读5分钟。”当我能够做到这点之后，阅读的时间就逐渐延长到10分钟、15分钟，最后30分钟。“我能够坚持阅读30分钟啦！”在成就感的驱动下，我又相继完成了1小时的阅读，这个成功的经历激励我实现了每天晨读一小时的目标。如果我一开始的目标就是每天阅读1小时的话，那我绝对是坚持不下来的。我肯定会在早起阅读过程中遇到挫折，我的改变是通过不断积累小的行动来实现的。\u003c/p>\u003cp>（how)我把这个方法称为“时间5开始”(1)列行动：列出一件具体的行动，比如读书，(2)找阻碍：找到对你而言会阻碍行动的点，不爱早起，读不下去（3）设动作：设置最容易启动的动作，从5分钟开始实施行动，读5分钟开始(4)作总结：阶段性的作总结，比如一个星期或者一个月总结一次，体验行动带来的成就感，(4)加时间：在5分钟的基础上持续增长时间。\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>这个5分钟开始的行动方法什么时候用呢？可以在一些我们想尝试的一个新行动的开始阶段运用。也可以用在一个行动的突破阶段，再多做一点。是在一件具体的行动上涉及到有时间因素的事件上。时间因素作用较弱的事件不适用于这个方法。\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>5分钟的时间是否过短，不足以体验到成就感。5分钟是个建议参考时间，大家可以根据自己容易启动又可以带来成就感的时间段为起点。比如8分钟或者10分钟，根据自己的规律来，关键在于让我们在“我能做”这个阶段体验充分，增进持续做的动力。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1激活经验：（显像提问法）\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>2分钟）\u003c/strong>\u003c/p>\u003cp>现在我们来练习一下刚刚学到的方法，请大家回忆一下有没有这样的经历:设定好一个行动目标：养成跳绳运动的习惯，制定了详细计划，起点太高，难以坚持，跑步减肥，发觉是项不容易见效果的事情，有些灰心，学习一项新技能，无从做起，想着想着就算了，请你回想一下，上个周，你设定一个行动目标后，现在却感到没什么进展？想一想：开始实施时你是怎么做的？是什么让你没有做下去？下面给大家1分钟时间思考，然后在小组内分享。\u003c/p>\u003cp>分享者：刘阳\u003c/p>\u003cp>我爱读书，每每读到一些关于儿童发展有关脑的内容的时候，我觉得脑发展在孩子成长的阶段很重要，就像系统读读关于脑发展的书籍。但是都只是在头脑中想想就算了。到现在还没有买书去看。\u003c/p>\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>反思加工\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>学习者拆为己用\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>7-8分钟）\u003c/strong>\u003c/p>\u003cp>现在我们来看你上周没有达成实施的事件，你会如何运用“时间5开始”的四个步骤，开始实施你的新行动。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>学习者一：刘阳\u003c/p>\u003cp>我想我得开始买书了，然后在众多书里，读起来的时候，读一会脑科学的书。我得看看列出书单，然后开始买书。\u003c/p>\u003cp>那现在你的行动目标是列出书单？还是开始读已经买好的关于脑科学的书？（反馈）\u003cbr>是我买好书了，我可能会看这本，看那本，而没有去看关于脑科学的书。我想我的目标是：每天看书的时候能看脑科学的内容。\u003cbr>那如果我们用“时间5开始”这个方法，来帮助你实现每天读书的时候读脑科学方面的内容。你会如何做呢？（反馈）\u003cbr>(1)列行动：每天读脑科学的内容，(2)找阻碍：看不进去关于脑科学是书，更愿意读其他书籍。（3）设动作：最容易启动的动作那我可以从5分钟开始实施行动，读书的时候，读脑科学内容读5分钟(3)作总结：阶段性的话我每个星期做一次总结，看看我读了多少脑科学的内容，读的怎么样(4)加时间：在5分钟的基础上持续增长时间。读10分钟半个小时等。\u003c/p>\u003cp>\u003cstrong>过渡\u003c/strong>\u003cstrong>：\u003c/strong>刚刚我们学会了在开始一个新行动的时候，我们可以从时间的因素作用上，通过最短的时间入手，突破自己的阻碍，让自己体验到我做到了的成就感，支持自己容易开始下一次的行动，实现持续行动。如果一项目标，涉及的不是一件行动内容，而是包含很多内容，我们都要入手同时去做么？我们可以从数量的角度入手，从简单的事情入手，开始实施行动，给出自己做出总结，体验成就感，在达成三件行动后更新新的行动内容。\u003c/p>\u003cp>下面我们阅读一下第二份拆页。现在请大家用2分钟的时间阅读。读完后请举手示意我一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13435,"quote":"\u003cp>\u003cstrong>过渡\u003c/strong>\u003cstrong>：\u003c/strong>刚刚我们学会了在开始一个新行动的时候，我们可以从时间的因素作用上，通过最短的时间入手，突破自己的阻碍，让自己体验到我做到了的成就感，支持自己容易开始下一次的行动，实现持续行动。如果一项目标，涉及的不是一件行动内容，而是包含很多内容，我们都要入手同时去做么？我们可以从数量的角度入手，从简单的事情入手，开始实施行动，给出自己做出总结，体验成就感，在达成三件行动后更新新的行动内容。\u003c/p>\u003cp>下面我们阅读一下第二份拆页。现在请大家用2分钟的时间阅读。读完后请举手示意我一下。\u003c/p>\u003cp>\u003cstrong>R阅读原书拆页：（二）（35-40分）\u003c/strong>\u003c/p>\u003cp>“行动科学管理术”认为，“培养新的行动习惯时，最多不要超过三个”。比如，在教新员工工作内容的时候，首先从最简单的三个开始，当员工能够熟练掌握这三项工作内容之后再继续教他接下来的事。\u003c/p>\u003cp>当你准备开始某项行动时，也应该按照这个法则来进行。\u003c/p>\u003cp>如果你想学习英语，每天只需要记三个单词。如果你想养成运动的习惯，每周只需要运动三次。当然，也有一些情况是无法严格按照“三”的数量来进行计算或区分的，在这种情况下只要感觉工作量不是太大就可以了。采用这种方法的关键在于，从所完成的一件一件的小事中，我们会确实地体会到“我做到了”的成就感。让自己充分地体会到成就感所带来的快乐，给自己褒奖，让自己享受自信。通过自己给予自己“好的结果”，让自己更容易开始下一次的行动。既然你想要改变自己并且拿起了这本书，那么你肯定想要变得更好。但是，正如前文中提到过的那样，如果一开始就把目标定得过高，只会起到相反的效果。所以一开始请把目标定得低一些，循序渐进一步一个脚印地开始行动。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解指导：（\u003c/strong>\u003cstrong>3-4分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003cstrong>二：\u003c/strong>希望学完这个拆页后，我们在目标包含很多行动内容的情况下，在开始实施的阶段，能够运用“数量3开始”的小行动，从简单的小事开始，体会到“我做到了”的成就感，让自己容易开始下一次的行动，更新新的行动内容，促进目标的达成。\u003c/p>\u003cp>(WHAT)作者通过阐述“培养新的行动习惯，最多不要超过三个”的观点，向我们展示了，\u003c/p>\u003cp>(WHERE)在设定一个目标后，开始实施行动的阶段，(WHY)目标定的过高会阻碍行动的启动，从而让我们觉得“我做不到”，导致难以坚持，我们可以在开始实施行动的时候，从简单能行动起来的数量入手，体会到我做到了的成就感，让自己容易开始下一次的行动。(HOW)在实施行动的阶段，怎么运用“数量3开始”这个行动方法促进目标达成呢？\u003c/p>\u003cp>(1)&nbsp;列行动：明确目标下包含的行动，一一列出，\u003c/p>\u003cp>(2)&nbsp;选3项：行动数量在3以内，在行动清单中找出最简单的三项内容，开始实施行动，\u003c/p>\u003cp>(3)&nbsp;做总结：评估反馈自己掌握了这三项内容\u003c/p>\u003cp>(4)&nbsp;更行动：在掌握三项内容的基础上，更新行动内容。简称“数量3开始”\u003c/p>\u003cp>简称“数量3开始”\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不那么做的坏处：\u003c/strong>\u003c/p>\u003cp>当我们在设定一个目标后，实施的内容比较多，通常会怎么做？\u003c/p>\u003cp>为自己制定详细的行动计划表，每个内容都实施起来；没什么具体规划，想到哪件就做哪件；\u003c/p>\u003cp>看着这么多的内容感到头大，拖延起来......这样做法的结果很可能因为标准过高无法坚持，持续不够不了了之，压力过大无法实施，最终让设定的目标或半途而废或流于形式或拖延不动。\u003cstrong>（一般的做法和后果）\u003c/strong>\u003c/p>\u003cp>在一个目标下包含很多行动项目的时候，实施行动的阶段，采用恰当的方法，更利于促进目标的实现。我们来体验一下。举个例子。\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>小明经常饮食不规律，爱吃辣，晚饭时间晚，饭后睡觉。去医院体检后发现有胃炎，需要调整饮食习惯。小明信誓旦旦的要全面开始调整，一日三餐，荤素搭配，七分饱，不吃辣，饭后运动，调整饮食时间，多餐少食....太多的事情需要做了，想想脑袋都大了。\u003cstrong>（简短的反例）\u003c/strong>\u003c/p>\u003cp>如果小明应用“数量3开始”的行动方法，他要怎样养成合理的饮食习惯呢？(1)列行动：列车目标下包含的行动，一一列出调整饮食习惯的可能涉及到的内容，比如：一日餐饮数量，每次餐饮是否定量，餐饮搭配，辛辣食物、不易消化的食物、餐后运动等(2)选3项：行动数量在3以内，在行动清单中找出最简单的三项内容，开始实施行动，一日三餐，每餐七分饱，每餐不含辣。(3)作总结：反思总结自己掌握了这三项内容，这样切实体会到自己饮食的变化。(4)更内容：在掌握三项内容的基础上，更新行动内容，可以做到以上三点后，可以荤素搭配，餐后运动等，以此养成合理膳食的习惯。\u003cstrong>（用how转反例为正例）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>“数量3开始”这个方法，可用在开始实施的事件比较多，比较难的情况下，就像刚刚调整饮食习惯和书中提到的新员工从所有项目中提出三项技能开始熟练掌握，而后增加项目以达成目标。也可以用在具体的数量上，比如背单词，一次背三个。比较容易启动。我们可以从数量的角度入手，从小行动开始。\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>开始实施的三件事里，其中一件事就压力很大难以启动呢？我们可以再细分这件事情当中的3件事去入手。根据自己的节奏和能力来，关键在于让我们在“我能做”这个阶段体验充分，再增加新的内容来实施，促进目标的实现。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3促进参与（预先设计好的案例场景，或者意译原书案例，请一组做当众表达或者角色扮演）\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>10-15分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景设计\u003c/strong>\u003cstrong>：\u003c/strong>我们刚刚学习“数量3开始”的行动方法，现在一起做个演练！请大家认真听一下将要演练的场景：小张时比较忙，没时间运动。随着年龄的增长，肚子上的赘肉上无底线的增长，是的，小张迎来了大多数人都呐喊的目标：管住嘴，迈开腿，小张为自己设定了一个新年目标：减肥，从目前的130斤减到100斤。他找到做健身教练的朋友商量，鉴于小张的工作时间没有整块的时间去健身房，小张的教练朋友给小张提供了适用于小张日常可行的减肥计划。“数量3开始”的行动方案。\u003c/p>\u003cp>(1)&nbsp;列行动：明确目标下包含的行动，一一列出，\u003c/p>\u003cp>(2)&nbsp;选3项：行动数量在3以内，在行动清单中找出最简单的三项内容，开始实施行动，\u003c/p>\u003cp>(3)&nbsp;做总结：评估反馈自己掌握了这三项内容\u003c/p>\u003cp>(4)&nbsp;更行动：在掌握三项内容的基础上，更新行动内容。简称“数量3开始”\u003c/p>\u003cp>\u003cstrong>小组讨论\u003c/strong>\u003cstrong>：\u003c/strong>现在，请两个人一组，进行演练。一个人扮演小明，另一个人扮演教练，演练完完之后，和大家分享一下。\u003c/p>\u003cp>\u003cstrong>角色扮演：\u003c/strong>小张：刘阳&nbsp;&nbsp;教练：东俭\u003c/p>\u003cp>小张：亮亮哥，你看我现在胖成这样，我想今年开始减肥。你是专业的健身瘦身教练，有啥好的建议？\u003c/p>\u003cp>教练朋友：你想减多少啊？多长时间啊？\u003cbr>小张：今年一年的时间吧，我想减掉30斤， 我算了一下算是合理的一个范围，不知道能不能行。\u003cbr>教练朋友：时间体重都比较合理。你是想去健身房训练还是说日常减肥什么的啊？\u003cbr>小张：我最近太忙了，就日常减肥，不知道能不能行，我还担心自己坚持不下来，这都喊了挺多次了。\u003cbr>教练朋友：通过日常的饮食运动是可以达成减肥目标的，如果坚持下来，你的目标可以实现。\u003cbr>我们可以从小行动开始，来开展减肥这么目标。\u003cbr>小张：怎么做呢？\u003cbr>教练朋友：我们可以看看，在日常减肥这件事上我们都可以在哪些方面入手：比如饮食做什么样的调整，运动做什么样的调整。\u003cbr>小张：我平时三餐，一餐两碗米饭一份菜，不经常吃肉。运动方面我想跑步，或者餐后散步，平时组队踢球。\u003cbr>教练朋友：那你这米饭的量可以调整，你吃饭快不？餐后散步是想晚餐后？\u003cbr>小张：我吃饭的速度基本上是我认识人中吃的最快的。餐后散步也就只能晚上了，平时太忙了，或者也可以早上上班的路上，又担心赶时间。\u003cbr>教练朋友：关于日常调整饮食和运动都可以减肥的。咱们可以列出来我们可以做的事情\u003cbr>1.一日三餐，每餐一碗米饭，一份青菜。2.荤菜吃肉的话尽量吃瘦肉，不吃油炸食品。3.吃饭过快，时间充裕的晚饭时间，每口咀嚼10下，这样带来饱腹感，减少饭量。4.早饭后去上班的路上走10分钟。5.晚饭后散步30分钟。6.每周去踢球.7.买跑步机在室内跑步半个小时。\u003cbr>小张：日常减肥这么难啊，这么多事情要做啊。\u003cbr>教练朋友：我们先列出来，现在我们从这些项目里找到三个，开始做起来。\u003cbr>（从文中看也有一些情况是无法严格按照“三”的数量来进行计算或区分的，“3”的关键在于容易和简单。不简单的指三件事情。你们可以从列出来有助于减肥的行动项目里找出最容易执行掌握的三项内容。\u003cstrong>（\u003c/strong>\u003cstrong>关联到原文知识点的回答反馈\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>教练朋友：你觉得哪三项内容是你能够最简单的入手的或者两项也行。\u003cbr>小张：我选三项吧，1,3,5我觉得我很容易做到。\u003c/p>\u003cp>教练朋友：选好三项内容以后，你给自己做个阶段性的反馈和总结，评估自己在这三项行动上做出改变的效果。然后做到以后，我们在来增加新的行动项目，帮你减肥成功。\u003c/p>\u003cp>小张：好的，谢谢亮亮哥的建议，行动起来没想象中那么难啊。\u003c/p>\u003cp>\u003cstrong>反馈\u003c/strong>\u003cstrong>：\u003c/strong>感谢刘阳和东哥给我们带来的表演。向我们展示了如何运用“数量3开始”的行动方法去促成减肥这件事。\u003c/p>\u003cp>\u003cstrong>A2 催化学习者应用\u003c/strong>\u003cstrong>：\u003c/strong>下面我们进入规划应用环节\u003c/p>\u003cp>\u003cstrong>分步催化1\u003c/strong>\u003cstrong>：\u003c/strong>&nbsp;\u003c/p>\u003cp>我们总会设定目标，学习一个新技能，完成一个比赛，戒掉不良的习惯，养成一个新的习惯，而这些新的目标中包括很多行动内容，我们设想一下，在未来一周的生活中，你要设定什么目标，这个目标可能包含很多内容。给大家5分钟时间思考一下，一会请小伙伴们进行分享。注意：只需要说出场景即可。\u003c/p>\u003cp>\u003cstrong>学习者案例一\u003c/strong>\u003cstrong>：\u003c/strong>场景：\u003c/p>\u003cp>学习者一：郑紫钰\u003cbr>我在下周有一个目标，想练习发声技巧，保护嗓子。我最近讲课比较多，讲一会嗓子就不行了，我想以后我讲课避免不了要学习运用发声技巧，练习发声，保护嗓子。\u003c/p>\u003cp>分步催化2：刚刚各位已经跟小伙伴分享了未来自己要设定的目标，而且目标里包含着不止一个行动内容，现在你决定要实现这个目标，做出新的改变，运用“数量3开始”的行动方法，你会从如何开始实施你的行动？接下来，请小伙伴先在小组内分享一下。\u003c/p>\u003cp>\u003cstrong>学习者案例一\u003c/strong>\u003cstrong>：\u003c/strong>应用：\u003c/p>\u003cp>学习者一：郑紫钰\u003c/p>\u003cp>关于练习发声技巧，保护嗓子这个目标，我列出了一些行动内容：1网上的关于练习发声的视频课程2.学习腹式呼吸，躺卧在床上，肚子上放三本书，朗读课文，每天5分钟。3.站立头上顶着书，读书练习发音。4.找专业的老师评估一下目前自己发音的问题。5.讲课的时候尽量让嗓子休息，多喝水。\u003c/p>\u003cp>然后这些行动内容里我选了三项对我来说最简单的事情，1.3.5.开始入手。\u003c/p>\u003cp>作总结，关于阶段性的总结：我一星期总结一下，评估自己做到执行的程度。\u003c/p>\u003cp>更新行动内容：在掌握好这三个内容后，再把2和4我能入手做的事情实施起来。\u003c/p>\u003cp>\u003cstrong>回应反馈\u003c/strong>\u003cstrong>：\u003c/strong>谢谢紫钰的分享，在练习发声技巧和保护嗓子的这件事上，很好的用“数量3开始”的方法做了规划和即将做出的尝试。\u003c/p>\u003cp>\u003cstrong>强有力的结语\u003c/strong>\u003c/p>\u003cp>我们今天的学习已经接近尾声了，我们一起回顾一下我们今天所学习的两个拆页。“时间5开始”和“数量3开始”。在设定目标后，我们通过列行动、选行动、找阻碍、设置最小动作、做总结、加时间或者更内容等一系列的行动，来促进目标的达成。在小行动启动后，总结会给我们一个信息：“我能做”，这是持续做的动力，我们今天学习的“时间5开始”和“数量3开始”都是在行动的实施阶段中通过小行动的积累促成目标的达成。你有设定好的目标吗？用小行动开始你的改变吧。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1578286068000,"updated_at":1578287840000,"ria":true},{"id":7501,"topic":"利用“正念法”纠正“认知偏差”","learn_goal":"利用“正念法”纠正“认知偏差”，从而实现目标","remark":"运用“正念法”，纠正“认知偏差”，原谅真实的自己从而改变自己，顺利地实现目标","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"RIA何孔明","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"\u003cp>&nbsp; &nbsp; 亲爱的各位小伙伴，大家晚上好。感谢拆书帮，让我有缘和大家相聚在一起。我族谱名叫何孔明，我的三个标签是武术、道教、阅读，因为爱好，都分别有幸拜了师父，并行了拜师礼。学习武术，主要是为了强身健体，我认为健康是人生的第一目标；学习道教可以净化心灵，一切努力都是为了更有能力付出、而不是为了无限索取。阅读是为了寻找更好的自己，当下的认知会让自己迷失，而阅读可以拨开思想的迷雾。我身份证名叫何群龙，祝各位小伙伴都成为各自工作的群龙之首！\u003c/p>\u003cp>&nbsp; &nbsp; 接触拆书帮很偶然，因为阅读，一直在寻找更科学的学习方法。So，你懂的，“拆书”就是一种科学的学习方法。说到“拆”，很多小伙伴会联想到学生时代“剪报”的经历。我觉得类似，但又不尽相同。“拆”有拆解、分解的意思，有类似“庖丁解牛”的感觉。具体来说，这里的“拆”是转化和内化的意思，拆书是将知识转化为能力的过程。“剪报”是把自己觉得有用的知识从报纸上“剪”下来，也可以理解为“拆”下来，但后续不一定将知识转化为能力了。拆书的方法分为个人学习的拆书法和组织学习的拆书法。个人学习法叫RIA便签法。R（Reading）即“拆”，阅读原文片段，选择拆页，类似剪报；I（Interpretation）即“解”，用自己的话解释拆页内容。A（Appropriation&nbsp;）可以理解为“帮”，A1关联过去经验，A2、A3规划具体应用：个人拆书法运用A2帮助自己未来行动、组织拆书法在拆书家的引导下运用A3帮助别人未来行动，这个过程就是转化和内化知识过程。所以，“拆书帮”是基于拆书法的学习爱好者社群组织，一帮会员以学习为载体，以线下活动的形式互帮互助，共同成长。具体表现为各地的拆书帮分舵，分舵性质为公益性青年组织，其使命是帮助学习爱好者成为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":10973,"quote":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R:\u003c/strong>《从行动开始：自我管理的科学》&nbsp;作者：石田淳\u003c/p>\u003cp>谷歌公司员工培训时也会用到的“正念法”\u003c/p>\u003cp>要想原谅真实的自己从而改变自己，顺利地实现目标，我们应该怎么办呢？\u003c/p>\u003cp>\u003cstrong>首先，我们必须认识到“自己的认知很容易出现偏差”\u003c/strong>。尽管我们无法完全消除脑海中的自动思考，但如果能够将“认知偏差”控制在最小，那么我们就能够有巨大的变化。\u003c/p>\u003cp>\u003cstrong>为了尽可能地避免“认知偏差”，关键在于正确地认清事实。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当发生某件事情的时候，应该只将意识集中在“眼前的事实”上，排除多余的印象、思考、喜恶，只接受其最真实的状态。\u003c/strong>这种方法被称为“正念”或者“ACT(Acceptance&amp;Commitment Therapy)”，在心理和精神医疗领域都很被重视。\u003c/p>\u003cp>比如，你去银行发现ATM机前有很多人排队，那么你的认识应该只有“ATM机前排长对了”。\u003c/p>\u003cp>“怎么这么多人，今天真是倒霉！”“第三个人怎么这么慢呢，这样午休时间不是都浪费了吗”这些都是与事实不相符的多余的想法。\u003c/p>\u003cp>如果\u003cstrong>只关注事实\u003c/strong>，那么当多余的思考和感情出现的时候，你也不会被其束缚，而会想“我的想法真无聊”。\u003c/p>\u003cp>“正念”是比之前被广泛应用的“认知行为疗法”更为有效的方法。\u003c/p>\u003cp>所谓“认知行为疗法”，就是纠正“认知偏差”，让患者从心理问题中解脱出来的治疗方法。现在越来越多的上班族被“一上电车就肚子疼”的毛病所困扰。甚至有比较严重的患者因为害怕突然出现的便意而不敢搭乘停车站较少的电车。\u003c/p>\u003cp>实际上，电车里并没有会让人肚子疼的东西，所以“一上电车就肚子疼”完全是一种认知的偏差。\u003c/p>\u003cp>如果休息的时候出去玩坐电车没事，下班的时候坐电车也没事的话，那么或许实际情况是“上班的时候搭电车就会肚子疼”。\u003c/p>\u003cp>但是，这仍然与真正的事实还有一段距离，一定还有更本质的原因。\u003c/p>\u003cp>或许因为去上班会引起人们的某种抵抗情绪，所以才会产生肚子疼的生理反应。这种抵抗情绪可能是因为与上司的关系不好、自身的业绩不佳或和同事之间有矛盾。如果找不出这些本质的原因，而只将注意力集中在“一上车就肚子疼”，那么不管吃多少治肚子疼的药也是没用的。\u003c/p>\u003cp>找出客观的原因，用正确的认知来应对，然后通过多次乘车来达到“就算坐车也不会肚子疼”的状态时，你才能彻底从苦痛之中解脱出来。这就是认知行为疗法。\u003c/p>\u003cp>“正念”法是在认知行为疗法的基础上，\u003cstrong>将注意力集中在“现在”和“现实”之上，纠正“认知偏差”\u003c/strong>的方法。\u003c/p>\u003cp>这种方法不只应用在心理疗法上。在美国，许多企业在对员工进行自我管理培训时都会采用“正念”的方法。谷歌公司为了提高员工的专注度和创造力，于2007年在全公司的员工培训中引入了这一方法。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; \u003cstrong>I:\u003c/strong>大部分小伙伴都读完了拆页，没有读完的小伙伴也请暂停，现在我们对拆页进行解读。\u003c/p>\u003cp>为什么我们很难开始行动，尤其面对需要要和他人产生互动的时候，更容易产生行动迟缓，比如演讲、社交、销售等。很多人在开始行动之前，心中预演了成百上千遍嘲笑、失败、拒绝的负面场景，结果自己把自己给吓住了：呆若木鸡，原地不动！\u003c/p>\u003cp>怎样才能轻装上阵呢？作者告诉我们可以利用“正念法”纠正“认知偏差”，这需要我们正确处理脑海中的想法：\u003c/p>\u003cp>1、\u003cstrong>认识到自己很容易负面思考，\u003c/strong>\u003c/p>\u003cp>2、\u003cstrong>只集中关注眼前的客观事实，\u003c/strong>\u003c/p>\u003cp>3、\u003cstrong>否定和排除主观的负面思考。\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;开车的小伙伴，都有过被人“别车”的经历。我们可以认识到自己脑海里很容易就产生“对方是不是故意的，是不是对我有意见”等负面思考；但此刻我们应该只关注“对方别我车了”这一客观事实。并否定和排除脑海中对对方的负面猜测，也许对方就是赶时间抢道而产生“别车”了。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>在面对陌生场合、上台演讲、独立销售或者和陌生人打电话的时候，我内心比较容易抗拒，比如在陌生场合，我会想对方会不会觉得我很害羞，不够开朗而不愿意和我交流；上台演讲时观众会不会嘲笑我气氛不够活跃、内容不够专业；销售或打电话时对方会不会烦我打扰到他。结果就是不到最后一刻，除非有人推动，否则很难行动。\u003c/p>\u003cp>2018年6月，我和合伙人生产了一批女性私密产品，正常情况我们都是把产品交给代理商或业务员销售，但这个产品销售情况不好，而产品的效期还有16个月，如果继续维持现状，几十万产品面临过期。所以，我和合伙人必须亲自下市场消化库存，同时给现有代理商和业务员打造样板市场。这对于在办公室做了多年销售管理，七八年不再做一线销售的我来说，现在需要独自下到一线市场，从事一线销售工作，觉得压力很大。到现在为止还处在间歇性踌躇满志，持续性不能行动当中。我脑海会想象客户拒绝，想象客户爱理不理的样子，因为这把年纪了，好歹也是一个管理人员，想想面子都挂不住；还会担心销售结果不好，甚至不如现在的代理商和业务员，更觉得没面子。总之，内心戏太多，导致一直没有行动。\u003c/p>\u003cp>\u003cstrong>A2:\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 目标：\u003c/p>\u003cp>从3月份开始每周工作日上午正常工作，下午下市场开发客户，每天至少开发一个客户。持续3个月，坚持到6月底、7月初，在3个月内消化库存。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、我认识到我在开发市场之前，有很多负面思考。我现在要减少把事情和情感关联在一起，把客观事实和主观情感相互独立。只看到需要开发市场这一客观事实，减少关联感受，并立即开始行动。\u003c/p>\u003cp>2、被客户拒绝，没有达成目标只是一个客观事实，不是因为谁对我有意见了。被客户拒绝后，承认事实，分析客观原因。\u003c/p>\u003cp>3、客户拒绝我也许是暂时没有需求，也许是不熟悉产品卖点，也许是还有同类产品库存......但这不是针对我的，嘲笑、拒绝等和对我有看法无关，我只要继续行动并优化流程就好。\u003c/p>\u003cp>最后，以电影《十分爱》里面的一句话做结尾：这世上任何事情都有障眼法，你看见的未必是真的，真的，你未必幸运能看见。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554508223000,"updated_at":1554509088000,"ria":true},{"id":6472,"topic":"情绪控制----嗲嗲","learn_goal":"今天给大家带来的片段是关于情绪控制的，学习完片段中的方法，我","remark":"片段给出了我们在受到不好情绪“嫉妒、不安、焦躁等易导致人们做出不好行为的情绪”影响时，帮助我们控制情绪的对策。它们是紧紧握住右手和数呼吸。","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"嗲嗲~","city":"葫芦岛市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是黄荣。是一个乐于分享，喜欢尝试新鲜事物，热爱思考的小仙女。下面由我给大家分享。\r\n分组：分享前给大家分一下小组，今天我们到场的伙伴并不多，分为两组好了，我左手边的伙伴一组，右手边的伙伴一组。请大家尽快调整。\r\n目标：今天给大家带来的片段是关于情绪控制的，学习完片段中的方法，我们能够在焦虑不安、烦躁、冲动、愤怒、情绪下用我们今天学到的紧紧握手与数呼吸的方法来控制住将要爆发的自己，避免做出那些不利于我们自身成长、会给我们带来不好影响的行为。这样工作生活不会被影响。\r\nFAB:今天带来的拆页来自于《从行动开始：自我管理的科学》这本书。\r\n F:作者是石田淳，他是日本研究行为科学管理第一人。他把从美国学习到的行为分析学和行为心理学方法改进为“行为科学管理”。也就是这本书中的方法。\r\nA:这本书不同于其他励志类书籍，书中的“行为科学管理”不讨论任何精神理论，而是将焦点集中于人的“行为”。在短时间内，便能让公司内八成的员工从“庸才”摇身一变成为“英才”，大受企业主和第一线的主管欢迎。书中强调行动而不是理论，很多书籍写的是理论，但是行动起来很难\r\nB: 本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！","ratings_count":1,"texts":[{"id":9781,"quote":"\u003cp>&nbsp;每个人都有自己心目中的理想状态。谁也不愿意让别人看到自己气急败坏的样子，而更希望在他人面前展现自己成熟稳重的形象。\u003c/p>\u003cp>所以，当一个人情绪激动的时候，也会对自己的愤怒感到不满，从而更加无法控制自己的感情。但他们其实在想：“快来一个人熄灭我的怒火吧！”\u003c/p>\u003cp>也就是说，一个陷入冲动状态的人，其实是他的心擅自离开了原本的地方而四处横冲直撞。这就导致他脱离了现实。\u003c/p>\u003cp>对于那些很容易冲动的人，应该先忍耐30秒。当你想要怒吼着爆发之前，只要忍耐短短30秒，那么事情将会变得完全不同。A先生就是因为没有等待30秒就让感情肆意宣泄出来了。\u003c/p>\u003cp>如果一个人连30秒都无法忍耐，那是因为他还没有习惯这种行为方式\u003c/p>\u003cp>接下来我为大家介绍两个帮助控制情绪的简单对策。当你感觉不安或者嫉妒时都可以使用这种方法。\u003c/p>\u003cp>对策一：紧紧握住右手\u003c/p>\u003cp>当你感到焦躁不安的时候，可以紧紧地握住右手。只需要这样一个动作就能奏效。\u003c/p>\u003cp>这就像暗示自己“不要冲动，保持冷静”一样。\u003c/p>\u003cp>当你被突然袭来的负面情绪所笼罩时，这样做可以使你不至于情绪失控，重新回到现实中来。\u003c/p>\u003cp>如果习惯握左手也可以。\u003c/p>\u003cp>对策二：数呼吸\u003c/p>\u003cp>在椅子上找一个舒服的姿势坐下，让身体彻底放松，缓缓地进行腹式呼吸。每次呼吸都数数，一直数到10。\u003c/p>\u003cp>这是非常简单的动作，所以在做的过程中头脑里可能会浮现出杂念，但不必担心受杂念影响而数错，如果真的忘记了数到几，请从头再来一遍。\u003c/p>\u003cp>数自己呼吸的次数，就算浮现出杂念也不必在意。通过重复这种简单的行动就可以使你的身心恢复平静，让你的注意力再次回到现实。\u003c/p>\u003cp>之所以推荐腹式呼吸而不是胸式呼吸，是因为腹式呼吸能调动副交感神经，产生放松的效果。 \u003c/p>","explains":"\u003cp>&nbsp;\u003cstrong>预防异议质疑或者困惑的讲解\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>：\u003c/strong>刚刚大家读过了原文拆页。拆页给出了我们在受到不好情绪“嫉妒、不安、焦躁等易导致人们做出不好行为的情绪”影响时，帮助我们控制情绪的对策。它们是紧紧握住右手和数呼吸。你可能觉得很简单，不就是握右手和数呼吸嘛。而且在情绪不好时可能都想不到这么做。但是我们要明确，自己紧紧的握住右手（或者左手）就像有一个人握住你的手一样，在制止你的行动，这个时候你的两只手就都不能做其他事情，所以这就不仅仅是动作上的控制，在心理上有一种束缚。数呼吸的前提是找到一个令自己舒服的姿势坐下，缓慢地进行腹式呼吸。你可能觉得深呼吸也可以，但是一般深呼吸用于解压，并不适用我们说的情况。\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>最近，我和其他几位同学一起准备比赛。我们需要一起找资料，之前开会已经明确了分工。但是说过之后没有人行动。本来时间就很紧，所以我很着急、焦虑，特别想要发火。但是由于学到了这个片段，所以我选择数呼吸。正好当时在寝室，所以慵懒的坐着，做腹式呼吸，数呼吸次数。这样过了一会儿之后就好了，和他们沟通，一起想办法。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用（分步催化1）:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>现在请大家想一想，在未来的哪些场景中，你会出现不好的情绪。这些场景可能是你需要赶时间，却越想快行动越慢；明明正在按照自己的计划行事，却出现突发事件打断了你的计划。给大家时间思考，然后请大家在小组内分享。\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录:\u003c/strong>\u003c/p>\u003cp>（1）将要有一场考试，要去陌生的地方考三科，在去考试时对陌生的环境会有紧张、焦虑的情绪。\u003c/p>\u003cp>（2）有了想法想和身边的朋友分享，可朋友却因为自己的事没有理，这个时候会有不好的情绪。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用（分步催化2）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>\u003cstrong>(\u003c/strong>\u003cstrong>逐字稿\u003c/strong>\u003cstrong>):\u003c/strong>刚刚的伙伴分享了可能出现的场景，那当场景发生时，你会如何运用今天学到的方法去控制自己的情绪呢？是通过仅仅握住右手，还是数呼吸呢？请大家根据自己的场景思考，想好之后就快和身边的伙伴分享你的应用吧。\u003c/p>\u003cp>\u003cstrong>学习者案例记录:\u003c/strong>\u003c/p>\u003cp>&nbsp;（1）在考场上可以坐在椅子上通过改变呼吸方式，进行腹式呼吸，然后数呼吸来减轻紧张和焦虑。\u003c/p>\u003cp>&nbsp;（2) 在朋友没有理自己时要控制自己的冲动，这时用仅仅握住右手的方法来控制住自己，避免冲动造成与朋友间的不愉快。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1542099955000,"updated_at":1542099955000,"ria":true},{"id":4831,"topic":"不要轻易否定自己，提升自我效能感","learn_goal":"掌握提升“自我效能感”的4种方法，让自己变成一个“易于调动情","remark":"在工作和生活中，我们每个人难免会遇到一些困难，遇到困难的时候，如果头脑中闪过“我大概做不到吧”，“我可能会失败”…这样的想法，失败的概率就会变大，结果我们真的失败了，然后我们越来越没有自信。认为自己真的是非常笨的人。而有的人即使遇到非常严峻的困难，总会坚信自己“总会有办法解决问题”，结果最后真的做到了。心理学上把这“能成功”的感觉成为“自我效能感”。《从行动开始》这本书提到要想让自己真的有所改变，有所行动，认同自己，提升“自我效能感”非常重要，并且提出了提升“自我效能感”的4个关键。","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"西瓜糖","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;大家好，我是西瓜糖，在一个教师培训机构研发部门工作,是一个不认同自己，特别想通过学习改变自己的新手拆书家。\r\n为了让自己变成更好的自己,我不断地开始新的尝试和学习，也在不断的半途而废着,任何事情都没有好的结果,后果就是越来越没有信心。虽然我放弃了学英语、练瑜伽，写文章等等，但是我却一直在拆书帮这个大家庭里慢慢的看别人成长。别的不说，我在2017年6月完成了RIA训练营的学习，该开始拆书了，又开始不自信起来，活动也不参加了，在线上拆书学习中，我意识到自己光有拆书的想法，不行动还是不会导出结果啊，我就应该看行动力的书，那让我《从行动开始》吧！\r\n说到我那么爱放弃，却从来没想过离开拆书帮，所以我要隆重的介绍一下我们的这个组织。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>第一次听到拆书帮这个名字，很多人都会想到是把书给拆散，其实这个“拆”指的是转化和内化，强调的是将书上的文字和内容转化为学习者自身的能力，而不是看过就忘了。那我们是通过什么方法来实现转化和内化的呢，就是简单易懂的RIA读书法，其中R代表阅读原书拆页，I代表用自己的语言重述原文知识，A则包括3部分，分别为联系自己之前的相关经验，以后该如何应用以及现场演练。我们自己读书的时候会用到A的前两部分，现场学习的时候就会有拆书家带领我们进行A的第三部分。所以，我们拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，如果你来我们拆书帮分舵，就会遇见许多爱学习的小伙伴。\u003c/p>\u003cp>那么知道了这个方法之后，我们就需要实践运用一下。请大家阅读一下手中的原文片段，这个片段是关于提升自我效能感的，读完的小伙伴抬头示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":7916,"quote":"\u003cp>“我大概做不到吧””我可能会失败”….一旦有这样的想法,失败的概率就会变大。因为你会被自己脑海中产生的负面情绪牵着走，很有可能会导致发挥失常。然后你就会认为自己“果然不行”，结果会使你更加没有自信，从而陷入恶性循环。而如果你感觉自己“能成功”，那么这种时候几乎都会成功。比如我自己，即便面对非常严峻的状况，也毫无根据地相信自己“总会有办法解决问题”，结果最后真的做到了。\u003c/p>\u003cp>大概你也有类似的经历吧？这种“能成功”的感觉，在心理学上有一个专业术语称之为“自我效能感”。“自我效能”在培养好的行动习惯和改变人生的过程中发挥着非常重要的作用。\u003c/p>\u003cp>“自我效能”的作用主要由以下四点产生：\u003c/p>\u003cp>1. 自己成功的经历：在此之前有过相同或者相似的成功经历\u003c/p>\u003cp>2. 替代性经历：虽然自己没有经历过，但看别人成功，因此认为自己也能够成功\u003c/p>\u003cp>3. 语言说服：即使自己对行动的成功毫无自信，但别人对你说“你能行”\u003c/p>\u003cp>4. 情绪和生理的变化：由成就感和喜悦导致生理状态发生变化\u003c/p>\u003cp>当你想要做什么事的时候，可以利用上述四点来提高你的自我激励能力。\u003c/p>","explains":"\u003cp>遇到困难的时候，有的人可能会觉得“自己可能会做不好”，然而这件事真的被搞砸了；而有的人可能会想“一定能有办法解决的”结果真的把这事做成了。心理学上把这种“能成功”的感觉称作“自我效能感”，“自我效能感”的人更容易快速调整自己的情绪，想办法达成目标，形成良性循环。\u003c/p>\u003cp>所以遇到困难时，我们可以这样做：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; 意识到自己是遇到困难，需要快速调整情绪，不能继续消沉，并分析出自己遇到困难的原因。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; 回忆自己成功的经历给自己打气：想想自己是否有与这次克服这样困难的相同或类似的经历，既然以前那么困难都克服了，这次一定也可以的。比如我们在学习一门新的语言时遇到困难，想想自己以前有过学习英语成功地经验，又把自己鼓舞起来了。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; 利用别人的成功经历激励自己：看到周围人都克服了困难，自己又没比别人差很多，自己应该也可以的。我在参加完RIA训练营后对拆书一直有畏难情绪，但是看到我地训练营同学宝仲、成成和马莉都成功晋级，自己觉得应该也可以的，所以也来拆书了。\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp; 利用语言劝服自己：想想如果是别人遇到这样的困难，我们会怎么说呢，现在就这样鼓励自己吧。当我们遇到困难想消沉时，领导同事的一句肯定和鼓励就会增加我们士气。当我们平时遇到困难时，自己应该怎么办呢？我们可以想想这事如果搁到别人身上，我们会怎样鼓励他，反过来我们就怎么鼓励自己。\u003c/p>\u003cp>有关“自我效能感”的很重要一点是我们的情绪和对自我认知，要想把自己情绪调动起来，不消沉，需要通过取得一丁点进步增强成就感。比如可以将眼下的任务分解成碎片化的，通过完成一小部分任务体验成功的快乐，激励自己继续下去。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>A1 联系具体经验\u003c/strong>\u003c/p>\u003cp>随着高考综合改革的深入，很多学校不知道如何进行学生的选课走班，以及课表的编排。和大家一样，领导也发现了商机，便让我负责这个项目进行“排课走班”产品的研发，但是我总是研究不出内容，研发过程推进不够。目前遇到的困难就是，我以前并没有在中学的教务处工作过，没有排课经验，所以也并不了解在高考综合改革的今天，学校遇到的困难具体体现在哪些地方；即使我了解了排课走班的大致方法后，仍然感觉很多具体的操作，我实现不了，反正就是领导要求我解决的实际问题，我都解决不了。我觉得自己太笨了，根本不适合做研究相关的高难度事情，只能做些简单重复不需要动脑的体力活。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>A2具体应用\u003c/strong>\u003c/p>\u003cp>那段时间真是焦虑的不得了，压根儿也不想来拆书帮参加活动，但在参加线上拆书时看到这本书，遇到这个片段，对我起到一定的帮助，觉得必须想办法让自己复活。\u003c/p>\u003cp>1.首先，我意识到自己总是因为困难或者达不成目标，就说自己笨，不适合干这个也不适合干那个。如果我不是意识到自己经常因为暂时的困难或者不是期待的完美，就会自我否定，然后又开始新的工作，我肯定越来越觉得自己一无是出，干什么都不行。\u003c/p>\u003cp>2.想到前段时间领导让我搜集整理“民办教育”的素材给他，我也是挺烦的，对于完全没有好奇过的领域，初看起来的时候都很困难，我不是看到一篇就整理一篇，最后也交出了漂亮的作业吗？我这次也不能光在这看了，也应该一边看文献资料一边做着PPT，应该慢慢就成型了。\u003c/p>\u003cp>3.这次去嘉兴考察，那的老师一开始也和我一样是普通的物理老师啊，也完全不懂排课表的事情，虽然花费不少时间最后也完成了学校的任务，总是能解决的，其他老师能做的，我也是可以的，只是时间而已。\u003c/p>\u003cp>4.如果是别人遇到这样的困难，我肯定建议他也看看周围的人也遇到困难，就像高考题你觉得难，别人也觉得一样难。在继续看别人浙江试点校，以及号称自己能排课的公司的困难后，我觉得自己不是太笨，大家都遇到相同的困难，我也可以继续研究下去的。\u003c/p>\u003cp>5.想想目前需要了解的内容都有哪些，找出比较容易解决的，先解决掉，一点点慢慢来。\u003c/p>\u003cp>我知道自己“自我效能感”低，但是一直也不知道怎么提升，通过这个片段我掌握提升自己的办法。同时我也相信自己会在不断完成拆书进阶的过程中，慢慢找到自信的，谢谢大家\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1521505924000,"updated_at":1530070510000,"ria":true},{"id":3586,"topic":"新行动从“三”开始","learn_goal":"通过片段的的拆解，掌握培养新行动的方法。","remark":"改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！《从行动开始》从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"李瑾","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好！我是李瑾，我现在是一级拆书家。今天我要完成二级拆书家TF2-1的补录。\r\n二、为什么拆解这个片段\r\n在很长的一段时间里，我不断给自己制定运动，锻炼减肥的目标和计划，但是每一次都没有长时间的坚持，最后都是以放弃结束，看了今天要拆的这个片段，非常有感触，这个方法让我现在坚持了60多天，因此也希望把这个方法带给更多的人，帮助大家也能在希望坚持的道路上持续的走下去。","ratings_count":0,"texts":[{"id":6481,"quote":"\u003cp>\u003cstrong>F:\u003c/strong>《从行动开始》一书由日本作家石田淳所著，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>该片段的内容非常具有可操作性，通过该片段的拆解，可以让我们很快的开始新行动。\u003c/p>\u003cp>\u003cstrong>B:\u003c/strong>通过今晚拆书片段的分享，可以帮助你掌握培养新行动，并且立刻可以执行的方法。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>行动科学管理术认为，培养新的行动习惯时，最多不要超过“三”个。\u003cstrong>如果不那么做的话\u003c/strong>，可能我们会很快就放弃自己本打算坚持的行动。\u003cstrong>例如\u003c/strong>，减肥，如果一开始我就每天跑5公里，那么也许我第二天就会因为太过于困难而放弃。也就是在最开始的时候，我们把目标定的小一些，然后循序渐进。\u003c/p>\u003cp>\u003cstrong>如何开始新行动的步骤是\u003c/strong>：\u003c/p>\u003cp>1、确定想要开始的新行动，例如，学习英语，阅读、写作……\u003c/p>\u003cp>2、确定自己可以轻松坚持的工作量，例如，每天背3个单词，阅读10分钟，写100个字……\u003c/p>\u003cp>3、行动起来，坚持21天以后，增加工作量，例如，每天背10个单词，阅读20分钟，写200个字……\u003c/p>\u003cp>4、以此类推，循序渐进。\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>&nbsp;&nbsp;该方法适应于任何一种想坚持的行动。\u003c/strong>\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>各位伙伴在工作、生活中，有没有遇到过这样的情况，下定决心开始某种新行动，例如准备背英语单词，或者是运动减肥，或者是阅读，但是，刚开始这段行动还没有几天，却又放弃了？\u003c/p>\u003cp>尔真：时间管理方面的知识已经学习2年，列清单这件事情，一直无法坚持。每天会写很多重要的事情，但是总是完不成，心里很痛苦。未完成的事情往后顺延，就导致事情越来越多，也就越来越无法完成，后来就索性放弃了。列清单这件事一直拿起又放弃，又拿起又放弃。\u003c/p>\u003cp>森森：学习英语。暑假里，一天学习5个小时的英语，坚持了2.3天就放弃了。\u003c/p>\u003cp>馨月：减肥。去年有成功，但是后来过年就没做，又胖了6斤。现在想重新开始，发现运动的强度很高，身体受不住，也就放弃了。\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>想象最近想要开始的那些行动，运用今天学到的方法，思考一下，如何开始，才能让自己坚持下去？可以在纸上写出来。结束后，请小伙伴们分享。\u003c/p>\u003cp>尔真：今晚开始，列行动计划只列3点。坚持1个月。\u003c/p>\u003cp>森森：先测试一个小时背多少个单词。然后每天背20-50个单词，不超过一小时。\u003c/p>\u003cp>馨月：每次游泳1500米。用15天做恢复训练，一星期做基础训练。一周4次20分钟的HIT运动。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1504486482000,"updated_at":1504486482000,"ria":true},{"id":3522,"topic":"拆解《从行动开始》","learn_goal":"通过拆解片段，提升精确数值，把握变化的能力","remark":"本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"郑珊珊","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天的拆书家郑珊珊，我今天要带领大家拆的片段源于《从行动开始》，《从行动开始》一书由 [日]石田淳所著，日本研究行为科学管理第一人，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！","ratings_count":0,"texts":[{"id":6401,"quote":null,"explains":"\u003cp>行动都是可以量化的，通过精确数值，把握变化，对养成好的行为习惯至关重要。\u003c/p>\u003cp>常遇到学生抱怨，常常制定目标，却也常常无法完成。大部分是因为太模糊，比如说，我想成为有钱人，这样的目标就很难去完成，因为没有一个具体的衡量标准。如，多少钱算是有钱人？什么时候成为有钱人？\u003c/p>\u003cp>比如说书中有提到公司规定为了增加员工内部的交流打招呼的次数，这种目标是太模糊了，要增加多少次招呼才算是更积极的打招呼？数值要精确才利于员工理解和行动。\u003c/p>\u003cp>我也常有这样的情况，常说要好好读书，但是没有一个数值作为衡量标准，所以也一直都没有实行。不是行动力欠缺，而是指令不够清晰。所以我会把这些目标具体化，比如说每天看一个番茄钟的书。\u003c/p>","interaction":"\u003cp>瑾:年年说减肥，但是年年减不下来。主要是管不住自己这张嘴。\u003c/p>\u003cp>月:我之前减肥成功一段，但后来没有控制，又复发了\u003c/p>\u003cp>康:我之前看书，没有目标很难实现，后来我自己给自己制定了一个目标，每天要做多长时间，后来一直在坚持，还算做得不错。\u003c/p>\u003cp>森:我想好好英语，但不知道从何开始，后来上了一个新东方的网课，通过阅读理解来记单词，只定个四天的目标，会比较容易实现。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1503960662000,"updated_at":1503960662000},{"id":3421,"topic":"轻松开始新行动","learn_goal":"通过片段的的拆解，掌握培养新行动的方法。","remark":"改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！《从行动开始》这本书分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！通过本次拆书片段的分享，可以帮助你掌握培养新行动，并且立刻可以执行的方法。","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"李瑾","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好！我是李瑾，我现在是一级拆书家。今天是TF2-1的第二次补录！\r\n二、主题介绍\r\nF:《从行动开始》一书由日本作家石田淳所著，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！\r\nA:该片段的内容非常具有可操作性，通过该片段的拆解，可以让我们很快的开始行动起来。\r\nB:通过今晚拆书片段的分享，可以帮助你掌握培养新行动，并且立刻可以执行的方法。\r\n三、为什么拆解这个片段\r\n在很长的一段时间里，我不断给自己制定运动，锻炼减肥的目标和计划，但是每一次都没有长时间的坚持，最后都是以放弃结束，看了这个片段，非常有感触，这个方","ratings_count":0,"texts":[{"id":6283,"quote":null,"explains":"\u003cp>行动科学管理术认为，培养新的行动习惯时，最多不要超过三个。\u003cstrong>如果不那么做的话\u003c/strong>，可能我们会很快就放弃自己本打算坚持的行动。\u003cstrong>例如\u003c/strong>，减肥，如果一开始我就每天跑5公里，那么也许我第二天就会因为太过于困难而放弃。也就是在最开始的时候，我们把目标定的小一些，然后循序渐进。\u003c/p>","interaction":"\u003cp>【A1】激活经验（显像提问）\u003cbr>\u003c/p>\u003cp>各位伙伴在工作、生活中，有没有遇到过这样的情况，下定决心开始准备背英语单词，或者是运动减肥，或者是阅读，但是，刚开始这段行动还没有几天，却又放弃了？\u003c/p>\u003cp>尔真：时间管理方面的知识已经学习2年，列清单这件事情，一直无法坚持。每天会写很多重要的事情，但是总是完不成，心里很痛苦。未完成的事情往后顺延，就导致事情越来越多，也就越来越无法完成，后来就索性放弃了。列清单这件事一直拿起又放弃，又拿起又放弃。\u003c/p>\u003cp>森森：学习英语。希望看英语文献，于是就想学习语法。看了一次，就没有后续了。现在还是想找个契机把它捡起来。\u003c/p>\u003cp>馨月：减肥。去年有成功，但是后来过年就没做，又胖了6斤。现在想重新开始，发现运动的强度很高，身体受不住，也就放弃了。\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>想象最近想要开始的那些行动，运用今天学到的方法，思考一下，如何开始，才能让自己坚持下去？可以在纸上写出来。结束后，请小伙伴们分享。\u003c/p>\u003cp>尔真：今晚开始，列行动计划只列3点。坚持1个月。\u003c/p>\u003cp>森森：看20分语法视频。把6个小时的语法视频分段观看完。\u003c/p>\u003cp>馨月：每次游泳500米。用15天做恢复训练，一星期做基础训练。一周4次20分钟的HIT运动。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1502673910000,"updated_at":1502673910000},{"id":3339,"topic":"《从行动开始》之战胜诱惑","learn_goal":"通过片段的的拆解，学会战胜眼前诱惑的方法，进行保持行动。","remark":"改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！《从行动开始》从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！通过今晚拆书片段的分享，可以帮助你在面对诱惑时如何战胜诱惑的方法，让我们的行动继续坚持下去。","level":"TF2-2","duration":60,"status":0,"type":0,"chaishujia":{"username":"李瑾","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好！我是李瑾，一名希望不断成长，超越自己的生涯规划师。今天是我进行TF2-2的项目的补录。希望能顺利过关。\r\n二、主题介绍\r\nF:《从行动开始》一书由日本作家石田淳所著，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！\r\nA:该片段的内容非常具有可操作性，同其他的书籍比起来，这本书的内容虽然简单，但是特别可行。\r\nB:通过今晚拆书片段的分享，可以帮助你在面对诱惑时如何战胜诱惑的方法，让我们的行动继续坚持下去。\r\n三、为什么拆解这个片段\r\n在很长的一段时间里，我不断给自己制定运动，锻炼减肥的目标和计划，但是每一次都没","ratings_count":0,"texts":[{"id":6189,"quote":null,"explains":"\u003cp>如何战胜眼前的诱惑，实现目标呢？首先从意识层面：充分认识坚持本身就是很难的，不要给自己太大压力和自责。例如，减肥这件事，我可以不管跟自己说，坚持运动确实很痛苦，真的很难，我们可以从慢慢走开始。3个月不成功就半年，半年不成功就一年。放轻松就好。\u003c/p>\u003cp>第二从方法层面：专注于达成的益处，把益处写在纸上，最后反复阅读。还是面对减肥这件事，我经常会定下宏伟的目标，但是在坚持当中，总是会碰到美食的诱惑，然后便以失败告终。然而，看到这个片段之后，我按照书中所讲的方法行动，把减肥的益处写下来，例如，最重要的就是健康，长寿，有更多的时间去做我喜欢的事情，第二便是美丽，苗条的身材可以让我以后买衣服的时候不再那么纠结。\u003c/p>\u003cp>&nbsp; &nbsp;也许大家会觉得这样做太麻烦了，事实上，\u003cstrong>不这么做的话\u003c/strong>，总是开始又放弃，然后又开始又放弃，反而浪费的时间和经历更多。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>各位小伙伴最近一段时间有哪些目标想要实现的？\u003c/p>\u003cp>从意识层面来看，你会如何跟自己对话，认识坚持本身就很难，让自己没有那么大的压力和自责呢？\u003c/p>\u003cp>馨月：减肥。\u003c/p>\u003cp>尔真：早睡。不早睡，身体会很糟糕，黑眼圈会很难看，第二天不精神，憔悴。一直都这样告诉自己，但是很难坚持。通过今天这个分享，有很多诱惑让我很难去早睡，从意识层面，我要先原谅自己，要不然就是双重打击。不要那么逼自己，给自己一个月的时间，12点睡觉，如果不行，就12点半，给自己缓冲的时间。\u003c/p>\u003cp>馨月：去年，减肥成功，但是现在又反弹了，很自责。今天这个片段让我知道，一切都过去了，先原谅自己，再重新开始。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>实现你的这个目标可能会有哪些诱惑让你偏离或者放弃行动呢？\u003c/p>\u003cp>当你遇到这些“诱惑”时，你会怎么做呢？\u003c/p>\u003cp>根据拆页内容，把坚持目标带来的益处写在纸上。\u003c/p>\u003cp>馨月：第一，可以带来很多美丽，穿好看的衣服。第二，提升自信心。第三，健康。健康又能带来很多的好处，例如可以做自己想做的事情。最棒的一件事就是人生从此可以更精彩。\u003c/p>\u003cp>尔真：早睡的好处。第一，早睡，很眼圈会缓解甚至消失。第二，早睡可以让第二天能早起，这样就会有很多的时间用来阅读和写作。第三，早睡，我的精神状态就会越来越好。第四，身体会越来越健康。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1501636442000,"updated_at":1501636442000},{"id":2758,"topic":"如何跳出恶性负面情绪","learn_goal":"通过掌握两个情绪提醒的小技巧帮助学习者从负面情绪中跳脱出来","remark":"“身边大牛这么多，我一个小菜是不是不行啊！”\r\n“老板又把难题丢给我是不是想让我早点走啊”\r\n“健身班的人都能下一字马了，我还啥都学不会，好丢人！”......\r\n   这些是负面思考你知道吗？\r\n   如何跳出负面思考，关注行动产生正向积极效果了？快来拆书吧！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"shuangdengmm","city":"成都"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【自我介绍】【1min】\r\n 大家好！（微笑 ，环视全场）非常高兴在这里和大家相遇，我叫邓爽，来自于一家珠宝上市企业，从事了四年的培训工 作。我给我自己三个标签：\r\n1、牛排爱好者：最近疯狂的迷恋上了不同部位的牛排，都是自己做。\r\n2、健身初级爱好者：从去年开始慢慢学习健身，有住在罗湖区的小伙伴可以约有氧运动。\r\n3、单身狗，一个目前最让身边人BIBi的一件事。\r\n 我相信大家愿意把人一生最重要的事情：时间。花费在这一场3小时的地方。都源于一个共同的目的：想要成长，想要做的更好。那你就来对地方了。\r\n【RIA介绍】\r\n 拆书帮不同于其他普通的读书会，过去的读书会是简单的分享一段大家觉得写得好的文字，大家听一听感动，就是没有行动的事情。而拆书帮是建立在一个改变我们行为核心技能”RIA便签法“之上的全国青年公益组织。目前在全国有目前在全国有22个分舵 800多个会员 深圳有南山 福田分舵 龙岗分场。\r\n 它起源于我们帮主赵周老师的的一个偶然经历，公司花费大量经费让员工去培训，但是培训内容就是来自于我们的书本？那就有一个问题了？我们自己能不能花更少的钱去达到","ratings_count":0,"texts":[{"id":5509,"quote":"\u003cp>【图书介绍】1min\u003c/p>\u003cp>接下来和大家先介绍一下今天的这本书《从行动开始-有想法不如会行动》来自于日本石田淳、他本人担任企业创始人，同时是美国日本行为管理协会会员。这本书的核心理念就是：在不讨论任何精神理论，而是将焦点集中于人的“行为”，的行为管理学。在短时间内，便能让公司内八成的员工从“庸才”摇身一变成为“英才”，大受企业主和第一线的主管欢迎。\u003c/p>\u003cp>【拆解主题介绍】\u003c/p>\u003cp>今天和大家分享的主题是当我们陷入负面思考的时候如何跳出这个坑，促使自己关注现实。\u003c/p>\u003cp>【阅读片段】2min\u003c/p>\u003cp>【原文片段】\u003c/p>\u003cp>Y小姐凭借自己的努力进入进入一家大型公司工作，她觉得自己的人生是一片光明的。但是不久她发现身边的同事好像都是精英，只有自己是懵懵懂懂的，之后她却每天都陷入了消沉和低落的情绪中度过。\u003c/p>\u003cp>“大家都做的这么好，只有我不行。和我一起入职的人进步已经这么大了，未来肯定没有的我位置，对公司而言我只是一个负担。”Y小姐不断重复这些话，自己陷入负面思考的恶性循环中，最后连公司都不想去！\u003c/p>\u003cp>为什么会这样？\u003c/p>\u003cp>人沉浸在自己的情绪中，逃避一时的困难，将会给自己带来更大的麻烦，道理好像很简单，但是很多人选择眼前的安逸，就好像很多人明明知道有很多工作要做，但是依然选择把时间花费在浏览网页上一样。\u003c/p>\u003cp>Y小姐其实仅仅通过和上司和同事的沟通寻求帮助是不够的，最重要的是需要停止多余的负面思考。这其实用一些小习惯就可以避免。\u003c/p>\u003cp>如何避免？\u003c/p>\u003cp>技巧一：弹手腕上的皮筋\u003c/p>\u003cp>这是高尔夫选手经常使用的减压方法：在挥杆前产生“自己有可能打不进”的不安情绪，影响发挥时，就用手指抓起皮筋弹一下，让思考回到现实和现在。\u003c/p>\u003cp>技巧二：转移夹子或皮筋\u003c/p>\u003cp>当头脑出现负面情绪时，将左边口袋的夹子或皮筋转移到右边口袋，一天以后数一数自己右边口袋的夹子，这个方法的关键是让你意识到原来我产生了这么多的负面思考。\u003c/p>\u003cp>当你意识到这一点之后，就会抛弃这些无意义的负面的思考了！\u003c/p>\u003cp>阅读完片段的小小伙伴可以点头示意我一下。\u003c/p>","explains":"\u003cp>【I原文复述】5min\u003c/p>\u003cp>（what）这个片段非常的简单，就是告诉我们当我们产生一些负面的情绪和思考的时候，采用两个技巧点在我们产生负面情绪或者思考的时候，用皮筋弹我们一下。提醒我们跳出负面情绪，关注当下做得事情。其实在应对负面思考有很多技能，我们选择了两个比较简单容易上手的和大家分享。这件事大家要注意这件事听起来很容易，做起来却不是每个人都能及时做到，为什么？\u003c/p>\u003cp>（前提）其次你要意识到什么是负面思考，它出现的表现形式是什么？\u003c/p>\u003cp>比如今天老板教给你一个难缠的顾客，你心理想说：“哎呀！这人很难搞定的，老板是不是想借着这个让我自己早点走人啊？”\u003c/p>\u003cp>比如当我们去健身房跳操课学瑜伽的时候，看着旁边那些人熟练的动作，你心理想说：”大家都做得这么好，我做的这么丑好丢人啊！“其实这种刻意否定自己，打击自己的想法都算是负面思考。\u003c/p>\u003cp>（why）首先我们要明确为什么我们要及时处理我们的负面思考：\u003c/p>\u003cp>负面的思考并不能在我们遇到困难瓶颈的时候从行为上帮到我们，给我们好的事情的结果。相反给我们增加了很多的心理压力，导致一系列的问题：比如那个健身，我想很多女士都会有这种感受，开始几天早点去排了前面，然后默默的从中间站到了最后一排，最后默默的从一周三次变成了一周一次。结果发现钱也白花了！\u003c/p>\u003cp>在工作中最常见是自己给了自己很多负面暗示，导致你想要逃避可能的结果，就去刻意拖延这件事。诱发了我们耳熟能详的拖延症，降低自己的工作效率。甚至影响到自己的年终绩效奖金。这些结果是我们不太希望发生的。\u003c/p>\u003cp>（where）当我们明白和意识到后果、负面思考的的特点的时候，片段中的两个技巧点就可以在你工作、健身、大型比赛的时候，脑海里一旦浮现出这些不利你的负面想法时，提醒你，醒一醒不要被负面思考干扰，回归到现实中来。\u003c/p>\u003cp>（how ）文中就采用弹皮筋或者数夹子提醒你这只是你自己内心的负面想法而已，让你意识到原来你在做事的时候，并不是事情本身有多难，而是你应该跳出来去关注事情的本身。\u003c/p>\u003cp>最后：在这两个技巧中大家有没有发现你是需要道具的，橡皮筋、或者夹子。我个人会觉得传统的橡皮筋有点不好看，也会换成带有弹性的运动手环、计数的夹子如果没有可以替换成任何可以计数的比如 弹珠、回形针等等。\u003c/p>","interaction":"\u003cp>【A1】1Min\u003c/p>\u003cp>那在这里我也和大家分享一段我自己没有意识到自己负面情绪，并且沉浸在其中不可自拔的恶性案例。\u003c/p>\u003cp>我在高一的时候身高是155 体重是110斤，那时候觉得身边的女孩子都很漂亮，也很有人缘。总觉得自己没什么朋友，长得也不太好看。就怎么想都觉得自己是一个又丑又没有人喜欢的人，经常会对自己说：“别人都那么漂亮优秀，我又算什么！什么都不是而已。”看到有漂亮的女孩子在班上说话，我只会默默坐到一边去，什么好像都打不起精神，做什么好像都是错的！有人跟我说话我都会觉得别人只是可怜我而已，那两年我没有朋友，开始陷入到很负面的生活，每天通过吃东西来发泄，得了暴食症！体重也飙升到了136斤，这是我当年18岁的照片。\u003c/p>\u003cp>其实这也是我分享这个片段的本质目的，不要让你脑海中的负面情绪毁了你的生活。意识到它的存在，用两个小习惯提醒你这只是你的负面想法，要从里面跳出来关注到事情上。\u003c/p>\u003cp>【A2】1min\u003c/p>\u003cp>在我上周在跑步的时候，每次跑到1.5KM 的时候，就会觉的呼吸不过来，这时候脑子里总会说：“哎呀！跑不动的，以前年纪小的时候都跑不了，更何况现在还在做办公室。”。后面我就会走完两公里。这种情况维持了一周，我很不喜欢这种感觉。所以在5.1-5.5号的跑步锻炼的时候，我会给自己带一个运动手环，跑到1.5KM的时候有这种想法时候可以用运动手环弹我一下。提醒自己不要掉到负面思考中，要专注跑步。\u003c/p>\u003cp>这周我正在完成一个课程PPT的美化，比较费时比较长，但是结果很重要， 我再做的时候不知道威为什么老是跑神跑去溜达网页，总觉得有人在跟我说：“反正都做的也没有XW做的好，你干脆留着等他回来吧！”我不太喜欢我自己这样的想法，所以在五一之后我会在办公室增加一个小盒子，每当我有这样的想法的时候就丢一个回形针进去，提醒我自己，不要被负面思考干扰，好好做我的PPT。\u003c/p>\u003cp>这个就是我今天的分享，我今天的分享目标就是帮助大家如何意识并提醒自己负面思考干扰到了你，如果大家对后续如何采取进一步的正面行动，如何更专注自己的行为提升效率。我们福田场不见不散。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1496112307000,"updated_at":1496112430000,"ria":true},{"id":2735,"topic":"学会如何战胜诱惑，专注目标","learn_goal":"通过片段的的拆解，学会战胜眼前诱惑的方法","remark":"","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"李瑾","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好！我是李瑾，，一名希望不断成长，超越自己的生涯规划师。我现在是一级拆书家。今天我要完成二级拆书家TF2-2的项目，顺利的话，我很快就会成为二级拆书家了！","ratings_count":0,"texts":[{"id":5483,"quote":null,"explains":"\u003cp>\u003cstrong>主题介绍\u003c/strong>\u003c/p>\u003cp>F:《从行动开始》一书由日本作家石田淳所著，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！\u003c/p>\u003cp>A:该片段的内容非常具有可操作性，同其他的书籍比起来，这本书的内容虽然简单，但是特别可行。\u003c/p>\u003cp>B:通过今晚拆书片段的分享，可以帮助你在面对诱惑时如何战胜诱惑的方法，让我们的行动继续坚持下去。\u003c/p>\u003cp>\u003cstrong>为什么拆解这个片段\u003c/strong>\u003c/p>\u003cp>在很长的一段时间里，我不断给自己制定运动，锻炼减肥的目标和计划，但是每一次都没有长时间的坚持，最后都是以放弃结束，看了这个片段，非常有感触，这个方法让我在面对诱惑时，继续坚持下去，因此也希望把这个方法带给更多的人，帮助大家也能在希望坚持的道路上持续的走下去。\u003c/p>\u003cp>\u003cstrong>I:讲解引导\u003c/strong>\u003c/p>\u003cp>如何战胜眼前的诱惑，实现目标呢？首先从意识层面：充分认识坚持本身就是很难的，不要给自己太大压力和自责。第二从方法层面：专注于达成的益处，把益处写在纸上，最后反复阅读。例如面对减肥这件事，我经常会定下宏伟的目标，但是在坚持当中，总是会碰到美食的诱惑，然后便以失败告终。然而，看到这个片段之后，我按照书中所讲的方法行动，把减肥的益处写下来，例如，最重要的就是健康，长寿，有更多的时间去做我喜欢的事情，第二便是美丽，苗条的身材可以让我以后买衣服的时候不再那么纠结。也许大家会觉得这样做太麻烦了，事实上，不这么做的话，总是开始又放弃，然后又开始又放弃，反而浪费的时间和经历更多。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2:(分步催化一）\u003c/strong>\u003c/p>\u003cp>各位小伙伴最近一段时间有哪些目标想要实现的？实现这个目标可能会有哪些诱惑让你偏离目标呢？\u003c/p>\u003cp>馨月：减肥。体重控制在115，练出马家线。\u003c/p>\u003cp>尔真：写作。今年的目标。\u003c/p>\u003cp>馨月：美食，懒惰。\u003c/p>\u003cp>尔真：追求完美。每天要完成的事情变成了生活的负担，就很难坚持下去。\u003c/p>\u003cp>\u003cstrong>A2:(分步催化二）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>馨月：远离美食。每天需要有东西来唤醒自己行动，想自己的痛点，胖了以后很丑，小有成就后，希望有人来认同自己。\u003c/p>\u003cp>尔真：写短点。学习方法来改变。情绪对坚持很重要。\u003c/p>\u003cp>馨月：远离病痛。越来越年轻。获得自信和美丽。体验极限运动。\u003c/p>\u003cp>尔真：锻炼反思、逻辑、洞察能力。塑造自己品牌影响力的方法。赚钱。不用强迫自己每天都去写，但也不放弃写作的动力。把益处贴在家里的办公桌上。不断阅读。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495980699000,"updated_at":1495980699000},{"id":2695,"topic":"学会如何培养新行动","learn_goal":"通过片段的的拆解，掌握培养新行动的方法","remark":"","level":"TF2-1","duration":17,"status":0,"type":0,"chaishujia":{"username":"李瑾","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好！我是李瑾，我现在是一级拆书家。今天我要完成二级拆书家TF2-1的项目，顺利的话，我很快就会成为二级拆书家了！\r\n二、主题介绍\r\nF:《从行动开始》一书由日本作家石田淳所著，本书完整介绍了在日本和美国广受推崇的“行为科学管理方法”，启发我们重新审视自己的认知和行动目标，掌握行动的最基本法则，灵活有效地规划自己的生活，学会不抱怨、不盲从，从而找到适合自己的人生道路！改变自己，一天花三小时去“想”，不如一天花五分钟去“做”！本书从分析我们日常生活中的“认知偏差”入手，系统科学地介绍了在日本和美国广受欢迎的“行为科学管理方法”，权威指导加真实案例，引导读者走出行动误区，关注当下，简化目标，丢掉“该做的”，找到“想做的”，科学系统地进行自我管理，简单有效地分解工作，轻松提升行动力！\r\nA:该片段的内容非常具有可操作性，通过该片段的拆解，可以让我们很快的开始行动起来。\r\nB:通过今晚拆书片段的分享，可以帮助你掌握培养新行动，并且立刻可以执行的方法。\r\n三、为什么拆解这个片段\r\n在很长的一段时间里，我不断给自己制定运动，锻炼减肥的目标和计划，但是每一次都没有长","ratings_count":0,"texts":[{"id":5482,"quote":null,"explains":"\u003cp>行动科学管理术认为，培养新的行动习惯时，最多不要超过三个。如果不那么做的话，可能我们会很快就放弃自己本打算坚持的行动。也就是在最开始的时候，我们把目标定的小一些，然后循序渐进。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>\u003c/p>\u003cp>各位伙伴在工作、生活中，有没有有过想要开始一段新的行动的，但是却放弃的经验？\u003c/p>\u003cp>尔真：时间管理方面的知识已经学习2年，列清单这件事情，一直无法坚持。每天会写很多重要的事情，但是总是完不成，心里很痛苦。未完成的事情往后顺延，就导致事情越来越多，也就越来越无法完成，后来就索性放弃了。列清单这件事一直拿起又放弃，又拿起又放弃。\u003c/p>\u003cp>森森：学习英语。希望看英语文献，于是就想学习语法。看了一次，就没有后续了。现在还是想找个契机把它捡起来。\u003c/p>\u003cp>馨月：减肥。去年有成功，但是后来过年就没做，又胖了6斤。现在想重新开始，发现运动的强度很高，身体受不住，也就放弃了。\u003c/p>\u003cp>\u003cstrong>A1+:\u003c/strong>\u003c/p>\u003cp>结合片段中谈到的方法，请大家分享接下来打算如何开始自己的新行动？\u003c/p>\u003cp>尔真：今晚开始，列行动计划只列3点。坚持1个月。\u003c/p>\u003cp>森森：看20分语法视频。把6个小时的语法视频分段观看完。\u003c/p>\u003cp>馨月：每次游泳500米。用15天做恢复训练，一星期做基础训练。一周4次20分钟的HIT运动。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495509150000,"updated_at":1495509267000},{"id":2662,"topic":"让每天的压力和行动可视化","learn_goal":"学会用可视化的方式来管理行动和压力","remark":"","level":"TF1-2","duration":14,"status":0,"type":0,"chaishujia":{"username":"林德鸿","city":"福州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天给大家领拆的这本书是《从行动开始--自我管理的科学》\r\n首先我给大家介绍一下什么是自我管理。自我管理其实就是字面上的意思，自我管理，就是管理自己的行为，管理自己的情绪，管理自己的状态。然后我们这本书的作者石田淳是研究日本行为管理第一人，行为科学管理研究所所长、美国行为分析学会会员、日本行为分析学会会员。这套方法被美国太空总署和波音公司在内的600多家公司采用，这本书或说这条方法的影响力还是相当广泛的。这本书相对于自控力这一类的科学比起来，他不是那种给你一整套系统的提高自控力的方法，让你长时间的训练，提高自控力。他只需要改变你的一些认知，你的一些想法，就得够收获到更好管理自己的行为的效果。我们获得改变的速度会更快一些。","ratings_count":0,"texts":[{"id":5396,"quote":null,"explains":"\u003cp>在我们接受到一件任务的时候，这个时候我们大脑内部会产生一系列的想法，我们怎么完成这件任务？这件事任务带了的影响，完成不了这个任务会怎样.......这些想法的产生伴随着一种力量，这种力量有助于我们完成任务，如果及时把这件任务完成，这就是很完美了。但是这个时候如果同时到来多件任务，就是产生各种各样的能量。当即时的情景无法我们同时处理，同时进行多件任务时，大脑的这些能量累计，压力就产生了。如果没有一个好方式的疏通这些能量，那么你的状态就可能变得烦乱。我们这个片段提供的方法，让我们把任务写下来或者用工具记录下来，这实际上就是把力量做一个释放。这样你的一个烦乱的状态就能够得到缓解。而且这还有个好处，你如果把他记录下来，你会顺便做一个排序，排序之后，你对其他的任务有了一个妥善的安排，你就更能心无旁骛的做当下的事情。事情可能会做的更加完善，同时对自己状态的把控也会更加精致。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>\u003c/p>\u003cp>这一段时间，当你得知同时进行多件任务的时候，你的状态是什么样的呢？\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>A:现在首先有两件对我很重要的任务，一件是准备两天后的培训，还有一个是运营，就这个运营，每天要看很多很多东西，就是相当与我每天要通知完成至少三四件事，然后在昨天，我突然接到一个任务，是做商业计划书，这件事让我很有压力，因为这个事情他很有难度，他要花我很多时间。这个事是在我每天已经有事情的时候来了，所以，很有压力。\u003c/p>\u003cp>\u003cstrong>学习者B\u003c/strong>:最近在自己创业阶段，很多事情都要自己亲手亲为，要联系厂商，要开拓市场等等....这件事本身就很多很多的任务，再加上家里的一些事情，还有我们的拆书帮三级的选拆页，这真的是很有压力的事情。\u003c/p>\u003cp>\u003cstrong>A2:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>如同书本所说，要想让我们从这些压力中解放出来，使用工具记录，这是一个好办法。下次遇到同时接到多任务的情况，你们会用什么样的工具把你自己从压力中释放出来呢？或者我们就借着刚刚说的事情，尝试着把他写下来，把头脑中的这些压力做一个释放。\u003c/p>\u003cp>\u003cstrong>学习者A\u003c/strong>:这是我现在写出来的计划，先是一个两天后的培训，我打算再16号，17号，18号三个晚上准备我这个培训的内容。商业计划书因为时间周期比较长，计划在20号之后完成。在白天的时间，会完成我的本职工作，做运营。嗯，这是我的A2。\u003c/p>\u003cp>\u003cstrong>学习者B\u003c/strong>:针对于我目前的工作，我要做的是针对我的目标客户群，我要做一个群解。第二个是针对现有客户群做一个深层次的沟通，就是每两天做一个沟通的跟进。第三是针对五一有一个大促，我想做一个初步的方案，然后再找人讨论一下。然后针对下周我的TF3-2,我现在已有可选的书目，我会利用零碎时间进行选择阅读。这是目前我对我工作的细分。\u003cbr>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495083725000,"updated_at":1495083725000},{"id":1995,"topic":"小而具体行动是一切解决问题的开始","learn_goal":"学会如何把工作任何分解为小而具体的行动","remark":"大家好！非常欢迎大家今晚来到我们拆书帮，和馨月一起进行一段愉快的旅行。今天对于我来说是一次非常特殊的活动，因为这将是我的TF1-1的考核阶段。首先跟大家做一个自我介绍，我叫张馨月，曾经是一家公司的HRM人力资源经理，后来生了宝宝，进入了陪伴宝宝成长的过程，也是一个非常幸福的过程，同时学习和成长是我一个不言而喻的必经过程，所以我来到了拆书帮。\r\n今天我为大家带来一本书《从行动开始》它的作者是日本作家石田淳。这本书讲了一些内容，对馨月来说影响最深的是“小而具体行动是一切解决问题的开始，也持续下去改变自我的开始”。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"张馨月","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！非常欢迎大家今晚来到我们拆书帮，和馨月一起进行一段愉快的旅行。今天对于我来说是一次非常特殊的活动，因为这将是我的TF1-1的考核阶段。首先跟大家做一个自我介绍，我叫张馨月，曾经是一家公司的HRM人力资源经理，后来生了宝宝，进入了陪伴宝宝成长的过程，也是一个非常幸福的过程，同时学习和成长是我一个不言而喻的必经过程，所以我来到了拆书帮。\r\n在座的各位有一些是第一次来到我们的拆书帮，可能不了解拆书帮和拆书是什么，那么我给大家做一个简单的介绍。拆书呢，是一个方法论，告诉我们不一样的读书方法，将书化为己用，同时以提升能力和解决问题为主旨；它也属于一种特殊的学习方法，有别与传统的升级考试的学习方法，专注人而非知识的本身。可以分为两个部分，一个是个人拆书，另一个组织拆书学习。个人拆书主要是运用便签阅读法，通过一本书的片段结合自身经验并落实到具体行之有效的行动中。组织拆书，是由一位拆书家通过对一本书的拆解，引领大家共同学习、分享，化书本中知识为自己能力的过程。拆书帮是基于拆书法的学习社群，它在各个城市以拆书帮（或称为拆书俱乐部）的形式存在，是一个青年共同学习非盈利公益组织，旨在培养更多可以","ratings_count":0,"texts":[{"id":4658,"quote":null,"explains":"\u003cp>对于馨月来说，我的I的部分是：使用行动列表，可以将复杂的工作分解成为一系列的小而具体动作和行动，让自己以后进行工作的时候有序可查，有准可衡，化繁为简。\u003c/p>","interaction":"\u003cp>我的A1的部分，刚好在前不久参加了一次海口TEDx活动，有幸成为一名志愿者，作为志愿者就不需要参加头脑部分的工作，例如环节的设计或是内部的决策工作。我们要做的是听从他们的安排，做小而具体的事就好了。在最好的碰头会上，进行任务的分配和工作的分解，我有幸被分配的是接洽组，具体的工作内容是与嘉宾、媒体和观众进行对接、引领。其实听起来是蛮简单的，可是当时到了现场真正去做这件事的时候，因为一些小的细节的事情没有处理的得当和大家分工并不是很明确，所以会出现这样的状态，演讲嘉宾、媒体、观众都一涌而来，没有办法进行细分，只好一起把他们引领到位，会出现一个短而小的混乱状态，但是整个会议整天下来也是非常成功的。可是我认为一个更好的会议是需要精确到每一个细节，针对今天我们看到的这个片段，对于我上次的工作进行一下总结和复盘。\u003c/p>\u003cp>进入我的A2，总结上次活动，我想将它放在我的工作岗位——接洽组来说更有发言权吧。对于我们接洽组来说，我们的人员配置是4个人，那我可以将工作分为两部分。第一个部分是接洽我们的演讲嘉宾和媒体，第二部分就是负责普通观众的引领。我们4人分为两组，嘉宾组和观众组。首先，嘉宾组在进行这个工作之前也就是与会之前与媒体和嘉宾进行电话沟通，如果可以的话也可以进行面谈，然后等当天工作之前，再进行电话确认，确认他们具体到达时间，到门口进行引领，接下来可以将工作分为以下几个步骤: 第一，当嘉宾来的时候立刻引到他们的嘉宾席，并且将他们带到我们技术团队面前，进行课件的传输和现场音乐的配置部分，同时赠送嘉宾礼物；第二，至于媒体的接待，将媒体引领到媒体区，同时告诉他们具体媒体工具摆放位置，配合他们进行线路的安装，再赠送嘉宾礼物。这样子整个工作就会有序进行。第二组的两个人是进行观众的引领。两个人可以进行以下的分工，其中一个人主要站在签到处，主要配合签到组分发胸牌，并根据胸牌不同颜色，引领他们进入会场，并转交给另一位工作人员进行第二步。第二位工作人员将转交过来的观众引领到相应的区域，并协助找到座位。通过以上工作的细致分工，我们就可以解决当时出现的混乱，进行人员的分流，使我们的工作更有效率。同时这里还想备注一点，人员进行过合理的配置，那么最好不要进行临时的调动，同时我们应该配置一个机动组，出现问题可以由机动组人员进行处理，例如接送嘉宾等一些工作。以上就是我对片段的分解，非常感谢大家的参加。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487582134000,"updated_at":1487582134000},{"id":1365,"topic":"如何让行动持续下去？","learn_goal":"顺利通过2-1","remark":"你是不是经常产生这样的想法，“我这个月要减肥”，“我明天要早起”，“我要摆脱消极的想法”，可就是从来没有实现过？\r\n你是不是经常觉得，“我想要学XXX，但时间不够；我工作很忙，但对XXX很感兴趣，有什么速成的方法吗？”\r\n本周拆书家带你拆解《从行动开始》这本书，学会如何让行动持续下去！","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是徐佳敏！大家可以叫我佳儿。很高兴今天能有机会来跟大家一起学习“如何让行动持续下去”。首先，我将用FAB法来介绍这本书。 【F】就是feature，特征。《从行动开始》这本书的作者是石田淳。他是研究日本行为科学管理第一人。他将科学分析人类行为的行为分析学和行为心理学方法改进为“行为科学管理”。指导了600多家公司和上万名上班族更好地进行自我管理。这本书比较简单，章节也很短，读起来很轻松，不会产生枯燥的感觉。【A】就是advantage，优势。这本书通过简单的概念和例子告诉我们误导我们很久的道理，豆瓣上超过80%的人评分4星和5星。有想法，不如会行动。教你如何更好地自我管理。【B】就是Benefit，利益。你是不是经常产生这样的想法，“我这个月要减肥”，“我明天要早起”，“我要摆脱消极的想法”，可就是从来没有实现过？你是不是经常觉得，“我想要学XXX，但时间不够；我工作很忙，但对XXX很感兴趣；有什么速成的方法吗？”那么，看这本书就够了，当然它不是要告诉你速成法，而是通过简单的“行动”两个字告诉你改变的本质。","ratings_count":0,"texts":[{"id":3862,"quote":"\u003cp>“开始行动”的关键在于“降低行动的难度”\u003c/p>\u003cp>比如第一次尝试跳马的人，一开始就跳8个箱子的高度恐怕是做不到的。应该首先从2个箱子的高度开始，然后一点点增加到3个或4个箱子，最后才能到8个箱子的高度。\u003c/p>\u003cp>为了健康而培养运动的习惯也是一样的，如果决定“每天走30分钟”那么肯定会很轻松地开始行动，但如果决定“每天跑5公里”结果就不一样了。你或许会找出“今天太冷了”“我有点感冒”之类的理由来拖延行动的时间。\u003c/p>\u003cp>另外，“制造好的环境”对于开始一项行动也非常有帮助。如果有一套很漂亮的运动服和一双穿起来很舒服的跑鞋，那么谁都会忍不住想要运动运动吧。甚至有人会邀请朋友一起运动。但是，就算有漂亮的运动服和舒服的跑鞋，还有朋友陪伴，每天只散步30分钟，为什么仍然有人连一周也坚持不下来呢？原因在于“没有得到好的结果”。\u003c/p>\u003cp>如果运动之后体重下降了，或者血压和血脂都控制在理想的范围之内，那所有人都会充满动力地坚持下去的。但实际上事情并不会那么顺利，所以很多人都会半途而废。\u003c/p>\u003cp>请回忆一下第一章中为大家介绍过的“ABC模型”的概念。当人们发现“能够立刻得到好结果”的时候，就会积极主动的重复这一行动。所以，如果运动无法立刻得到好结果，可以创造“好的结果”来刺激自己坚持运动。\u003c/p>\u003cp>也就是说，给坚持下去的自己准备一些奖励。\u003c/p>\u003cp>“行动科学管理术”利用“ABC模型”的概念来解释人的行动与结果之间的关系。\u003c/p>\u003cp>A=Antecedent（前提条件）\u003c/p>\u003cp>B=Behavior（行动）\u003c/p>\u003cp>C=Consequence（结果）\u003c/p>\u003cp>前提条件指的是引发行动的环境。比如，会议结束了（所以你去休息一下）；视力变差（所以你戴眼镜）；上司对你说“提交企划报告”（所以你提交报告）；朋友对你说“请你吃点心”（所以你吃了点心）......这些都属于前提条件。\u003c/p>\u003cp>“在上司的要求下提交了报告”“在朋友的邀请下吃了点心”则是一种行动。像这样促使人们采取行动的前提条件是必要的，但只有前提条件，无法使行动多次重复。\u003c/p>\u003cp>如果出现了提交报告却没有获得通过，点心很难吃等不好的“结果”，那么人们就不愿意重复这样的行动。但是，如果出现提交报告后得到了赞扬，点心很好吃等结果，那么人们就会自发地重复这样的行动。\u003c/p>","explains":"\u003cp>片段中提到的关于跑步的案例相信大家都有所感触，想要坚持运动，一开始就告诉自己今天要跑5公里往往是不可行的，行动必须是个循序渐进的过程，可以从开始的走路30分钟慢慢增加到走路1个小时再慢慢跑起来，跑起来之后再从跑5圈慢慢增加到跑10圈，当然仅仅循序渐进也还是不够的。片段中告诉我们，除此之外，还要制造好的环境，一身漂亮的运动服和舒服的跑鞋无疑会增加去跑的动力，同时像书中讲的利用“ABC模型”的理念在每次跑完之后给自己一些奖励让自己持续坚持下去，重复这一行动。\u003c/p>\u003cp>（举例）我们都想把自己要做的事坚持下去，可是听过那么多道理，依然过不好这一生，过去我也是在跑步和早起这两件事上颇费心力，依然没有养成习惯。看了这个片段之后，我明白我之所以没有做到就是因为我没有按照书里讲到的三个方法去做，我要跑步，我告诉自己今天要跑一个小时，然后，我每次都是这样说，每次都是最多只坚持三天就放弃了，我在穿着上也不注意，也没有想过如果自己坚持下来要自己什么奖励。同样，我要早起，我也从来都是一上来就说要5点起床，根本没有考虑自己的生物钟不能适应突然的调整，导致即便挣扎着起来了一整天的精神都不好。\u003c/p>\u003cp>（不这么做的坏处）由此看来，想要让行动持续下去，按照片段中介绍的方法是极为正确的。而我们如果一下子定任务的时候不考虑自己的实际接受情况，不去创造好的环境，不去给自己设定一些奖励来激励自己，那么我们很容易就又是三天打渔，两天晒网。次次定计划，次次以失败告终，次次从头开始恶性循环。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>那么大家听完我对片段的理解和我自己失败的例子，接下来，请大家回忆一下你上一次坚持做某事的场景，比如你上一次下决心早起的时候，想要坚持跑步的时候，坚持记单词的时候，坚持去健身房锻炼，决定减肥的时候，或者其他你坚持做的事，你当时的状态和结果是什么样子的？请回忆其中的一个场景，在小组内分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>木禾：每天晚上之前看会儿书，没有坚持下来，只会坚持两三天，就放弃了，还有记英语单词，也是三天打鱼两天晒网，\u003c/p>\u003cp>徐贵：练毛笔字，没有坚持下来后，现在又要从头开始。\u003c/p>\u003cp>A1+：\u003c/p>\u003cp>再遇到这样的情况，你可以怎样结合我们今天学习的“循序渐进”“制造好的环境”“给自己奖励”三种方法去处理？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>木禾：一天一天循序渐进，形成习惯。\u003c/p>\u003cp>徐贵：每周能坚持下来的话出去玩一下。\u003c/p>\u003cp>那我们今天分享了三种如何让行动持续下去的方法，“循序渐进”“制造好的环境”“给自己奖励”，希望大家回去能认真思考一下，如何用这三种方法让自己更好地行动，更好地坚持做想做的事，更好地做自我管理，那今天我的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479699656000,"updated_at":1479699656000,"ria":true},{"id":1363,"topic":"如何更好地规划我们的行动","learn_goal":"顺利通过2-4","remark":"    你是不是经常产生这样的想法，“我这个月要减肥”，“我明天要早起”，“我要摆脱消极的想法”，可就是从来没有实现过？\r\n你是不是经常觉得，“我想要学XXX，但时间不够；我工作很忙，但对XXX很感兴趣，有什么速成的方法吗？”\r\n本周拆书家带你拆解《从行动开始》这本书，学会如何让行动持续下去！\r\n","level":"TF2-2","duration":60,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫徐佳敏，今天我们一起学习如何更好地规划我们的行动。\r\nF 特征（核心是“书”，用于满足好奇心）：《从行动开始》这本书的作者是石田淳。他是研究日本行为科学管理第一人。他将科学分析人类行为的行为分析学和行为心理学方法改进为“行为科学管理”。指导了600多家公司和上万名上班族更好地进行自我管理。这本书比较简单，章节也很短，读起来很轻松，不会产生枯燥的感觉。 \r\nA 优势（重点是“比较”，用于建立安全感）：这本书通过简单的概念和例子告诉我们误导我们很久的道理，豆瓣上超过80%的人评分4星和5星。有想法，不如会行动。教你如何更好地自我管理。\r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）：你是不是经常产生这样的想法，“我这个月要减肥”，“我明天要早起”，“我要摆脱消极的想法”，可就是从来没有实现过？你是不是经常觉得，“我想要学XXX，但时间不够；我工作很忙，但对XXX很感兴趣；有什么速成的方法吗？”那么，看这本书就够了，当然它不是要告诉你速成法，而是通过简单的“行动”两个字告诉你改变的本质。","ratings_count":0,"texts":[{"id":3860,"quote":"\u003cp>人生在世，难免会遇到失败和挫折，这绝对不是“意料之外”的情况。如果将失败和挫折看作是 “难以接受的事实”，那么只能陷入不必要的失落情绪之中。\u003c/p>\u003cp>如果你在努力地 “改变自己” “达成目标”的过程中遇到困难，请不要气馁，应该理性地分析出现这种情况的原因，最好能够将这些原因都写出来。\u003c/p>\u003cp>比如，你好不容易持续戒烟三个月，本以为“这次一定能够戒烟成功”的时候，却在和朋友一起喝酒时无意接过旁人递过来的烟吸了一根。开了这个头之后，你又自己买了一包烟，一天就吸光了一整包。\u003c/p>\u003cp>在这种情况下，绝大多数的人都会觉得“我是一个没用的家伙”， 从而对自己进行猛烈的批判。这种自我批判多半是“自暴自弃”式的，非但不会出现“仅此一次，不会再犯同样的错误”的反省，还会出现“反正我也管不住自己， 干脆放弃戒烟” 的想法。\u003c/p>\u003cp>你不觉得这种想法很奇怪吗？\u003c/p>\u003cp>你只是偶然吸了一根烟，尽管你知道不应该。既然如此，只要你以后不坐在吸烟的人旁边，给自已营造一个与香烟隔绝的环境就可以了。\u003c/p>\u003cp>如果你想控制饮食，朋友却总找你去吃自助餐，那么你的目标自然很难实现。如果你认为 “现在改变自己是第一要务”，那么就把自己不能去吃自助餐的理由告诉朋友，拒绝和他们去吃自助餐。\u003c/p>\u003cp>如果想养成好的行动习惯，就营造一个能够养成好习惯的环境吧。\u003c/p>\u003cp>几天前，有一位在金融机构工作的女性来找我咨询。“我有一个因为工作原因一定要考的证书，每天下班后和周末休息的时候我都会为了准备考试而复习，但我一看书就犯困，于是就跑去床上睡觉。我的意志是不是太软弱了？我究竟应该怎么办才好呢？”\u003c/p>\u003cp>如果按照“遇到困难时，理性地分析造成困难的原因”的原则来思考, 那么答案就很明显了。如上述女性的情况，她在学习的时候不能处在身边有床的环境之中。那么只要走出家门去咖啡馆或者图书馆之类的地方复习就可以了。 听到我的建议之后，她顿时恍然大悟。\u003c/p>\u003cp>不管面对多么困难的状况，都不要认为自己是个没用 的人，因为这种想法是毫无意义的。自我贬低只会造成 “认知偏差”。冷静客观地分析状况，寻找解决方法，然后实践这个方法，这样就能避免陷入毫无根据的“认知偏差”之中。\u003c/p>\u003cp>不要冲动，保持理性。\u003c/p>\u003cp>不要主观，保持客观。\u003c/p>\u003cp>不要抽象，保持具体。\u003c/p>\u003cp>如果你很容易因挫折和失败而陷入低沉和失落的情绪之中，那么请用这三种态度来思考，寻找对策。这样你的心态就会端正一些，将精神集中在应该做的事情上。\u003c/p>","explains":"\u003cp>原书拆页提到我们在面对失败时容易陷入自我认知偏差，认为自己意志力薄弱，认为自己做不到想要做的事完全是因为自身定力不够，我们有的小伙伴之前有听过我拆解这本书其他的片段，我们在之前的学习中也提到过改变人生的是行动而非意志。\u003c/p>\u003cp>【强调不那么做的坏处】很多时候，我们做不到想要做的事，并非是因为意志力薄弱的问题，有环境因素，有外界的人力，物力因素，等等，如果单单总是认为是自己意志力的问题，那我们很容易陷入自暴自弃，永远都对自己没信心，永远都做不到想要做的事的恶性循环中。如果我们在失败时能够冷静客观，保持理性，认真具体地去分析自己失败的原因，然后从原因入手，寻找失败的源头，以此来解决问题，相信我们在之后的问题中就不会陷入上面所述的恶性循环中，会集中精力在要做的事情上，从而做到想做的事情。\u003c/p>\u003cp>【可能异议的预防性讲解】也许有人会说，想要戒烟，看到别人吸烟，自己也想吸；想要看书，看到床就不由自主犯困，这就是意志力薄弱的问题啊！可是大家想想看，我们每个人的天性就是趋利避害的，都是天性寻找舒服的，没有人会乐于吃苦的，只要认识到这一点，试着去离开那些让我们舒服但又阻碍我们进步的外界条件，比如去图书馆看书，周围都是学习的伙伴，而且自己也想要好好学习，这时候根本不会产生困倦感，反而可能会觉得自己意志力比较强呢！\u003c/p>\u003cp>【细化行动步骤】原书拆页提到面对失败的三种心态，看似官方的三句话，解读出来就是，当你没有做到想要做的事，首先，不要评判自己，不要自暴自弃，不要对自己失去信心，认识到这并不是意志力薄弱的问题；然后，冷静客观地去分析，为什么没有做到，是因为环境，别人的干扰，还是别的什么因素；最后，尝试如何去创造更不受干扰的外界环境，让自己把重心精力放在要做的事情上，而不是对自己的评判中。\u003c/p>\u003cp>【举例】拿我自己来说，在学习这个拆页之前，我确实是如果在某件事上失败了，我就会认为是我意志力薄弱，认为自己不够好，一直处于对自己的批判中，比如早起这件事，我知道我只有早起才能做完自己一天的任务，否则就每天往后拖了，那我就开始强迫自己早起，最近因为天气实在太冷，刚开始因为打了鸡血每天都很激动，然后过了几天就是，闹钟响了，实在太困，被窝实在太温暖，迷迷糊糊关掉闹钟继续睡，等起来后发现自己没有早起，就会深深地自责，为什么你做不到啊，你起不来你就完不成今天的任务啊，各种各种，意识到这一点之后，我开始反省，到底真的是自己意志力薄弱吗，闹钟离手太近，宿舍一晚上除了被窝，外面真的很冷，晚上睡太晚了，导致真的很困，当我冷静分析之后，我发现，有这么多因素我都可以改变，比如把闹钟离远一点，为了不吵到室友，我肯定在听到后第一时间要关掉它，就不会拖延了，被窝外面很冷，那我就提前拿个大衣在旁边，起来穿上大衣就不冷，晚上睡太晚，那就赶紧调整作息，早睡才能早起。如此分析之后，我就不再总是评判自己了，即便偶尔几次没有起来，也不会认为自己意志力薄弱或是怎样，毕竟人不是机器，我会更多地原谅自己，接纳自己。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>那听完我对于原书拆页的理解和我自己早起的案例，相信大家心里都或多或少想起了自己的一些失败经历，那么请大家仔细想一下，你过去有没有想要做一件事，比如你想要早起，想要学习某项技能，想要每天坚持看书，想要坚持去健身房锻炼或者坚持去跑步，想要在工作中能高效完成任务之后再刷手机，后来半途而废了，你当时是什么感受，你是怎么看待自己的？跟小组的伙伴分享一下，稍后我们请一位小伙伴跟大家一起分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>少侠：我最想坚持的一件事是写作，至少每天能写个500-1000字，但我常常坚持不下来，会给自己找很多借口，我今天太忙了，今天太晚了，我还是睡觉吧，要不就是今天特别想看一个电视剧，还有一种是今天实在没有灵感，我找很多很多的理由，怀着深深地歉疚去睡觉，早上起来的时候，就经常在被窝里很痛苦，我就觉得很自责，我觉得我连这样一个自己喜欢做的事情都坚持不下来，一方面很自责，另一方面否定自己的意志力和人格。这样长期让自己处于这种恶性循环里，特别不好。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>谢谢少侠的分享，刚刚少侠说了，她说她会给自己先找借口去不做这件事，不做了之后自己又开始自责，认为自己意志力薄弱，那刚刚学到了这个片段，我们意识到面对失败时不能主观，不能冲动，不能抽象，我们大家现在加工出一个案例场景，比如少侠打算继续坚持写作，你打算学习什么知识，打算做什么事情，假如你没有坚持下来，你要怎样在类似的情境中运用我们理性，客观，具体的原则进行分析，而不是评判自己？请大家在小组内分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>少侠：我主要的问题在于平常晚上的时候总会拖延，然后把事情都攒在晚上一起做，所以当我晚上做完的时候就觉得很累，没有精力，也没有时间，很困，第二天早上起来精力很充沛躲在被窝里自责，所以我下次再遇到这样的情况时，首先会想一下自己该怎么办，冷静地分析一下，我怎样才能把我写作这件事坚持下去，那我想到的就是把我写作这件事挪到早上，每天早上在没有人打扰的时候写，没有灵感的时候我就会在前一天，白天遇到一些事情随时随地地能够纪录自己的灵感和想法，这样我在写作的时候就可以梳理自己的思路。\u003c/p>\u003cp>拆书家：\u003c/p>\u003cp>少侠分享的很棒，她刚刚在上一个环节分享了她想要坚持写作但没有坚持下来，那通过我们今天的学习，假如自己在以后还想要做这样的时候，再没有坚持下来她会怎样客观地去分析，而不再是评判自己，那我们学习了面对失败时三种正确的心态，如何更客观理性具体地看待我们的行为，接下来我们就用一种新的ABC模型，帮助我们认清我们应该做的事，更好地完成我们要做的事，帮助我们更好地行动。如果在刚刚的分享中你想起了自己曾经失败的案例，或者自己以后想做的事，刚好我们接下来学习的片段可以帮助到你。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3861,"quote":"\u003cp>人们想要做的事，大致可以分为两种类型。\u003c/p>\u003cp>一种是像英语和跑步等 “可以让自己变得更好”的类型，也就是“明知道应该做什么好，但就是做不到”的情况。\u003c/p>\u003cp>另一种是像吸烟和暴饮暴食等应该减少的“过剩行为”，这是 “明知道不应该这样做但就是停不下来” 的情况 。\u003c/p>\u003cp>“行动科学管理术” 将需要增加的不足行为和应该减少的过剩行为，统称为 “目标行为”。 为了减肥而跑步和为了学英语而背诵单词等行为之所以无法增加，是因为这些行为如果不长期坚持下去就看不到成果。所以，我们很容易被眼前的诱惑所打败，这种情况下 “眼前的诱惑” 被称为 “竞争行为”。\u003c/p>\u003cp>比较一下早起跑步和睡懒觉，背英语单词和看喜欢的电视节目。与总是看不到结果的“可以让自己变得更好的行为”相比，人们更容易选择睡懒觉和看喜欢的电视节目。 而吸烟、暴饮暴食、赌博，虽然人们明知道这些行为会给将来的自己带来坏的影响，但却因为能够立刻获得眼前的快感而难以将其戒除。\u003c/p>\u003cp>你的目标行为究竟是想要增加的 “让自己变得更好的行为”，还是想要减少的“过剩行为”呢？首先你必须明确这一点，然后，为了10年之后的自己，现在的你必须做出改变。\u003c/p>\u003cp>你可以将自己的目标行为放在第一章介绍过的“ABC模型”之中。\u003c/p>\u003cp>“行动科学管理术”利用“ABC模型”的概念来解释人的行动与结果之间的关系。\u003c/p>\u003cp>A=Antecedent（前提条件）\u003c/p>\u003cp>B=Behavior（行动）\u003c/p>\u003cp>C=Consequence（结果）\u003c/p>\u003cp>前提条件指的是引发行动的环境。比如，会议结束了（所以你去休息一下）；视力变差（所以你戴眼镜）；上司对你说“提交企划报告”（所以你提交报告）；朋友对你说“请你吃点心”（所以你吃了点心）......这些都属于前提条件。\u003c/p>\u003cp>“在上司的要求下提交了报告”“在朋友的邀请下吃了点心”则是一种行动。像这样促使人们采取行动的前提条件是必要的，但只有前提条件，无法使行动多次重复。\u003c/p>\u003cp>如果出现了提交报告却没有获得通过，点心很难吃等不好的“结果”，那么人们就不愿意重复这样的行动。但是，如果出现提交报告后得到了赞扬，点心很好吃等结果，那么人们就会自发地重复这样的行动。\u003c/p>\u003cp>请准备一张纸，将整个行动的过程都写出来，关于C ( 结果)，不管是好的结果还是坏的结果都写出来。\u003c/p>\u003cp>如过剩行为 “吸烟”，我们能够找到许多A (前提条件) ： “有饭后一支烟的习惯” “随身携带香烟” “同事总会找自己一起去吸烟”。而C ( 结果) 则包括 “吸烟后放松精神”“吸烟后感觉后悔” 等等情况。\u003c/p>\u003cp>而让自己变好的行为，如“跑步”，则或许有“体检时发现身体出了问题” “变胖了裤子穿不下”“朋友邀请自己一起跑步”等A ( 前提条件），或许会出现“跑步之后心情舒畅” “变瘦了” “变得健康了”“感到疲惫”等C(结果）。\u003c/p>\u003cp>这样一来，你就可以客观地观察自己的状态了。\u003c/p>\u003cp>如果你的目标行为是需要减少的，它就是过剩行为， 那么应该首先消除A（前提条件） ，使其难以发生。\u003c/p>\u003cp>比如，你想要减少“吸烟”这个过剩行为就应该不买香烟，不随身携带香烟，扔掉家里的烟灰缸，不和吸烟的人接触。\u003c/p>\u003cp>但是，如果对比A（前提条件) 更有影响力的C（结果）置之不理，还是无法彻底戒烟。因为你知道吸烟后能立刻得到 “放松” 的效果，所以当有人给你烟的时候还是会吸。\u003c/p>\u003cp>在这种时候，我们就需要准备另外一个同样能够得到“放松”这一效果的行为。这种行为被称为“替代行为”。\u003c/p>\u003cp>能够得到放松效果的行为有“喝茶” “深呼吸” “冥想”等，可以选择一个适合自己的方案作为吸烟的“替代行为”。\u003c/p>\u003cp>另外还有一点，那就是关注“不行动所带来的结果”。不吸烟可以得到“健康”“省钱”“不被人嫌弃”等好的结果，只要能够意识到这一点，就可以控制自己不去做那些多余的行为。\u003c/p>\u003cp>另一方面，如果你的目标行为是需要增加的，它就是能让你变得更好的行为，那么和吸烟等过剩行为的情况刚好相反，应该尽可能多地增加A（前提条件），提高行动发生的概率。\u003c/p>\u003cp>如果你想要跑步的时候，可以“通过买一双漂亮的跑鞋” “找一种让跑步变得快乐的方法” “邀请喜欢的人一起跑步” 等提高自己跑步的频率。\u003c/p>\u003cp>另外，由于不足行为就算增加也不会立刻取得好的结果，所以我们需要为自己准备一些能够立刻获得快乐的事。通过 “跑步结束后喝一杯美味的饮料” “洗澡的时候使用浴盐”等自我奖励，来帮助我们坚持。\u003c/p>","explains":"\u003cp>原书拆页提到我们的目标行为有两种，不足行为和过剩行为。首先我们要认清楚哪些是我们需要增加的不足行为，哪些是我们需要减少的过剩行为，然后我们运用&quot;ABC模型&quot;来作为我们行动的原则。像吸烟就属于需要减少的过剩行为，读书就是需要增加的不足行为。对于过剩行为呢，减少它的前提条件A，寻找可以替代的结果C，同时关注不做过剩行为所带来的好处。对于不足行为，同样，我们要增加它的前提条件A，及时给自己奖励快乐的结果C，以此激励自己持续反复地进行行动B。\u003c/p>\u003cp>【强调不那么做的坏处】上一个片段我们已经意识到，失败时不能一味地评判自己，而要更客观地去分析原因，联系到刚刚这个片段，就是我们要按照这个ABC模型来分析我们的行为，如果意识不到我们的行为是过剩还是不足，就没有办法找到问题的源头，就更别说通过ABC模型来分析，同样，即便是我们分清了哪些是过剩行为，哪些是不足行为，如果我们不知道怎样创造条件来让自己更好地行动，而只是认为，嗯，我要减少过剩行为，我要增加不足行为，这也是没有意义的，这就是我们为什么要学习这个片段的原因。\u003c/p>\u003cp>【可能异议的预防性讲解】那么可能有同学就会问了，看似这个方法很简单，这要客观列出来，回去就能做，可是实际上，如果你的好朋友让你出去吃饭，你怎么能拒绝呢，如果早上想要早起但真的起不来啊。如果是这样的话，我们就要问自己，自己的核心目标是什么，把自己的核心目标放在首位，如果关系好的话，你的同学会因为你拒绝他而生气吗，如果想要早起而起不来，即便是运用刚刚分析的方法去做还是起不来，那你就要问自己，你是不是真的想要早起，早起是需要内驱力的，如果你没有内驱力，再多的方法也不管用。\u003c/p>\u003cp>【细化行动步骤】只要内心有自己的核心目标，接下来，我们就可以按照拆页中的信息规划我们的行动，接下来，请大家在发的那张纸的空白处写几句话，作为我们的行动步骤，待会儿我们在讨论中要用到这几个步骤。\u003c/p>\u003cp>1.写下你近期要做的事，要改掉的坏习惯，要养成的新习惯等等，按照过剩行为和不足行为区分。\u003c/p>\u003cp>2.分别写下每件事的前提条件A和结果C，越具体越好，越多越好。\u003c/p>\u003cp>3.如果是不足行为，那就增加A和C，如果是过剩行为，那就减少A，寻找替代行为，同时关注不行动带来的好处。\u003c/p>\u003cp>【举例】拿我自己来说，我想要多读点书，这是我需要增加的不足行为，写下这件事的前提条件A，有发现自己写东西没有素材，跟别人聊天没有深度，这都是前提条件，结果C有，腹有诗书气自华嘛，看书会困啊等等。那我先来创造多一点的前提条件A，比如在枕头边，书桌前，自习室的桌子上，只要我待的地方，我随处都放几本书，只要我想玩手机，我就会看到很多书，就会不由自主地拿起书，同时比如微信读书这个app，我把它放在手机主屏幕上，看到微信就能看到它，想起我如果多读点书，就能换书币买书，就会打开微信读书而不是微信，那增加及时奖励呢，就是如果我微信读书排名第一的话，我就会奖励自己周末去买只笔买个本子啊或者出去吃一顿。\u003c/p>","interaction":"\u003cp>A3：\u003c/p>\u003cp>现在听到这里，相信大家对今天要学习的内容有一定的理解了，现在请两个人一个小组，其中一位小伙伴扮演指导者，帮助旁边那位小伙伴完成我发的那张纸最后一页那个表格，你会怎么帮助他增加更多的前提条件和结果来做好不足行为，怎么减少前提条件，寻找替代行为来减掉过剩行为。请完成一件不足行为和一件过剩行为的解决办法。稍后我们请一组小伙伴跟大家分享一下。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>过剩行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>减少前提条件A\u003c/td>\u003ctd>替代行为\u003c/td>\u003ctd>不行动的好处\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>不足行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>增加前提条件A\u003c/td>\u003ctd>及时奖励\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学习者案例记录：\u003c/p>\u003cp>大庆，欢欢：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>过剩行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>减少前提条件A\u003c/td>\u003ctd>替代行为\u003c/td>\u003ctd>不行动的好处\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1 玩游戏\u003c/td>\u003ctd>有网；新买的手机，内存很大；有时间。\u003c/td>\u003ctd>对眼睛不好；睡眠不足，影响学习；愉悦，放松。\u003c/td>\u003ctd>控制用网的时间，主动断网；手机内存可以下载学习类APP；把时间合理安排。\u003c/td>\u003ctd>学习，看书\u003c/td>\u003ctd>保护眼睛，有充足的时间学习。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>不足行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>增加前提条件A\u003c/td>\u003ctd>及时奖励\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1 提升思维能力\u003c/td>\u003ctd>与周围人有落差，学习\u003c/td>\u003ctd>说话时没有思维\u003c/td>\u003ctd>看思维的书，用拆书帮的方法；跟别人交流促进。\u003c/td>\u003ctd>买书，与人分享。\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>A2：\u003c/p>\u003cp>刚刚听了这组小伙伴的分享，我们每个组刚刚其实都有一个人完成了这个步骤，那另一个人在听对方说的过程中也多多少少会使用，现在，请大家设想一下，刚刚我们在片段1中也提到了几个场景，需要增加的不足行为，比如有早起，读书，规划自己的工作，锻炼，等等，需要减少的过剩行为比如戒烟，睡懒觉，看剧，零食，跟朋友喝酒，等等，也可以是刚刚分享过的那件事情，只需要找出一件，自己思考一下，自己怎么分析它，怎么找到前提条件和结果，是增加呢还是减少呢，给大家两分钟的时间，规划出具体的步骤，在以后的学习工作生活中，自己要如此用到今天自己写的这些。稍后我们请一位小伙伴跟大家分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>大庆：\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>过剩行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>减少前提条件A\u003c/td>\u003ctd>替代行为\u003c/td>\u003ctd>不行动的好处\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1 吃零食\u003c/td>\u003ctd>包里装钱；手机支付宝微信都可以支付；男朋友惯着。\u003c/td>\u003ctd>花钱太多，长胖，第二天早上起来会拉肚子，满足，开心，睡眠不好\u003c/td>\u003ctd>少带点钱；从宿舍到教室会选择没有商业街的路去走；跟男朋友讲清楚不要惯着自己。\u003c/td>\u003ctd>多吃点水果。\u003c/td>\u003ctd>身体健康。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>不足行为\u003c/td>\u003ctd>前提条件A\u003c/td>\u003ctd>结果C\u003c/td>\u003ctd>增加前提条件A\u003c/td>\u003ctd>及时奖励\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>大庆分享的很棒，为自己分析的也很具体，为了不吃零食也是蛮拼的哦。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>我们今天学习了两个片段，大家还记得第一个是什么吗，面对失败时，保持客观，理性，具体，从容地去分析自己为什么会失败，接下来我们学习了如何利用ABC模型来帮助我们理清自己的过剩行为和不足行为，帮助我们更好地行动，贯穿今天的核心，还是客观，遇到事情，不要着急，理性地去分析，对症下药，才能更好地管理自己的人生。正像《从行动开始》这本书的核心一样，如果想要改变自己的人生，抱怨自己的缺点是没有用的，只靠意志力也是无法实现的，只有科学管理自己的行动，才能达到目标。希望我们在以后的工作学习生活中，能充分利用行动这个词来鞭策自己，跳出认知偏差，相信我们会过的越来越从容，谢谢大家，我今天的分享就到这里。感谢大家这么长时间的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479694870000,"updated_at":1479694892000,"ria":true},{"id":1181,"topic":"看清沉没成本，敢于面对失败","learn_goal":"顺利通过2-2","remark":"你是不是多次想放弃一件事但因为付出太多而一直舍不得？你是不是在不值当的事情上浪费了太多时间，精力，金钱，却迟迟不敢面对自己的失败。\r\n本周拆书家，带你学习《从行动开始》这本书，让你看清沉没成本，敢于放弃沉没成本，直面失败，直面自己的内心。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是徐佳敏！大家可以叫我佳儿。很高兴今天能有机会来跟大家一起学习“看清沉没成本，敢于面对失败”。\r\n首先，我将用FAB法来介绍这本书。\r\n【F】就是feature，特征。《从行动开始》这本书的作者是石田淳。他是研究日本行为科学管理第一人。他将科学分析人类行为的行为分析学和行为心理学方法改进为“行为科学管理”。指导了600多家公司和上万名上班族更好地进行自我管理。这本书比较简单，章节也很短，读起来很轻松，不会产生枯燥的感觉。 【A】就是advantage，优势。这本书通过简单的概念和例子告诉我们误导我们很久的道理，豆瓣上超过80%的人评分4星和5星。有想法，不如会行动。教你如何更好地自我管理。 【B】就是Benefit，利益。你是不是经常产生这样的想法，“我这个月要减肥”，“我明天要早起”，“我要摆脱消极的想法”，可就是从来没有实现过？你是不是经常觉得，“我想要学XXX，但时间不够；我工作很忙，但对XXX很感兴趣；有什么速成的方法吗？”那么，看这本书就够了，当然它不是要告诉你速成法，而是通过简单的“行动”两个字告诉你改变的本质。","ratings_count":0,"texts":[{"id":3555,"quote":"\u003cp>人类之所以不愿意接受确定的损失，是因为“不愿承认自己失败”。\u003c/p>\u003cp>我们就是这样害怕失败。\u003c/p>\u003cp>为了证明这一点，让我们再来做一个测试。\u003c/p>\u003cp>某铁路公司投入了巨额资金，开展将铁道线路延长到相邻城镇的工程。但某一天，该公司忽然发现这条线路完工后根本无法收回成本。如果你是这家铁路公司的社长，你会做出什么样的指示呢？\u003c/p>\u003cp>1. 继续施工。\u003c/p>\u003cp>2. 停止施工。\u003c/p>\u003cp>作为一名读者，从客观的角度来看，你一定会选择 “停止施工”吧。但是，如果你真的是这家公司的社长，那么你大概会选择 “继续施工。如今，针对许多公共事业是否应该继续开展的讨论越来越多。对于国土面积有限的日本来说，修建太多的机场，很明显是亏本的。应该说，尽快出停止施工的决定才能够将损失控制在最低范围。但是，即便知道继续下去毫无意义，很多工程还是因为之前投入的资金太多而“骑虎难下”。因为前期投入的金额会全部浪费，再加上不愿承败，很多亏本的事业都在继续进行。\u003c/p>\u003cp>在行为经济学中，将“已经支出且无法收回的费用称为 “沉没成本”。\u003c/p>\u003cp>“沉没成本”不只出现在与公共事业相关的事例中，在一切境况中，它都会对我们的心理造成影响， 妨碍我们最终做出判断。\u003c/p>\u003cp>比如你的朋友对你说：“我有一个好项目，你给我5万元，到时候我还你6万元。”结果你相信了他并且给了他5万元。但这种事很明显是假的，到时候别说6万元，恐怕连5万元都拿不回来。\u003c/p>\u003cp>当你催促那个朋友快还钱的时候，对方这样说：“项目还差1万元就能完成。所以你能再借我1万元吗？”如果你继续借钱给他，那么损失就将增加到6万元，但很多人抱着取回那5万元（沉没成本）的想法，都会会继续借出钱。\u003c/p>\u003cp>“沉没成本” 的概念在时间方面同样适用。\u003c/p>\u003cp>假设你从20 多岁的时候就以结婚为目的开始和男友交往，虽然后来你隐约觉得他是一个满嘴谎言的花花公子，但直到35 岁时，你才认清他的真面目。你本应该尽快与他分手并开始新生活，却会因为“不想浪费之前交往的时间”而犹豫不决难以做出分手的决定。\u003c/p>\u003cp>人类的一切行动都是以 “尽可能避免失败” 为前提的。这种想法本身并没有错。毕竟带着“我不想失败”的意识采取行动，总比带着“反正我是一事无成的人，失败也无所谓” 的自暴自弃的想法去行动要好得多。\u003c/p>\u003cp>但这说的是失败之前，面对已经出现的失败还是应该看清现实比较好。\u003c/p>\u003cp>不要执着于 “我其实想这样”，面对未来采取行动才能够取得好的结果。\u003c/p>\u003cp>正所谓失败乃成功之母，将失败看作是一种宝贵的经验才是最合理的做法。\u003c/p>","explains":"\u003cp>大家看完了吗，是不是觉得好似当头棒喝，过去，有多少次，我们想放弃一件事，却因为投入太多而舍不得。\u003c/p>\u003cp>【举例】我大概在去年下半年的时候，加入了一个绘画群，群主很热心，给我们制定了每天坚持画画打卡的任务，只要我们发上去，他都会点评鼓励，我在坚持了一个多月后，有点坚持不下去了，因为自己的画画天赋和水平实在是，但因为几个原因一直拖着没有放弃，首先，自己不想说自己不行，其次，群主那么热心，不想让对方失望，于是就继续坚持，但是自己明显感觉自己已经觉得痛苦了，画画水平没有提高，反倒增加了每天的压力。就这样一直到自己实在坚持不下去了才决定告知群主自己要放弃。\u003c/p>\u003cp>【可能产生的异议及预防性讲解】所谓“沉没成本”，相信大家看了片段中的几个例子都有了一定的理解，可是也许我们会想，是啊，我知道我也经常因为舍不得放弃沉没成本而继续一件错误的事情，但不是有句话说的好嘛，“听过那么多道理，依然过不好这一生”，大道理人人都懂，可一遇到真实情况，又有几个人能果断放弃呢？大家有没有想过一种情况，我们很多人都做不到放弃沉没成本，是因为我们害怕失败，我们害怕别人或者自己责备自己一事无成，付出了这么久还没有成果却要放弃，我们害怕承认自己的失败，但正因为意识到这一点，我们才更要及时放弃，把失败看作宝贵的经验，不让沉没成本变得更多。\u003c/p>","interaction":"\u003cp>拆书家提问设计：&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp;（分步催化1）\u003c/p>\u003cp>那大家听了我自己的例子以及我对于片段的理解，请大家想一下，在你工作，生活中，你都会为哪些事情花时间，花金钱，花精力？比如兴趣爱好的培养，恋爱，炒股，学习某个技能，上司布置的工作，等等。请在小组内讨论，稍后我们请一两个小伙伴给大家分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>A:追女生的过程中不愿放弃\u003c/p>\u003cp>大庆：在学校担任很多职务，又没办法取舍，所以花了很多时间。\u003c/p>\u003cp>（分步催化2）\u003c/p>\u003cp>那我们今天学习了放弃考虑沉没成本的知识，大家刚刚也讨论了自己最近遇到的情景，请大家加工出一个具体的例子，说明你今后在这样的情境下你要怎么做？请在小组内分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>B：我的沉没成本是关于画画这块，因为我小时候就学过国画，后来自己学习素描什么的，技巧跟功底已经不是很好了，但是我还是没有放弃，毕竟画的不是很好，我现在的想法是，如果我真的喜欢这个，我就会找专业的老师去学习，听老师的指导，这样我就能有方向性。\u003c/p>\u003cp>拆书家引导：那这是你觉得自己如果真的喜欢这个，那如果你发现自己听了老师指导，还是不得要领，或者说没有激情在这个上面，你要怎么办？\u003c/p>\u003cp>B：那我就会及时撤回在这方面的精力投入，转而去做更喜欢的事情。\u003c/p>\u003cp>今天我们学习了放弃沉没成本的知识，相信大家也都是有收获的，我来举一个以后的例子，假如你买了一张电影票，付了钱且不能退票，你看了一半之后，觉得不好看，这个时候，你是继续看完呢，还是理智地离开去做别的事情呢？还有当股票跌落的时候，你是继续等待相信它会回升还是及时收回成本，寻找新的投资机会？这两个都是关于沉没成本具体的案例，大家可以根据这两个案例帮助自己更好地理解沉没成本，也在以后的学习生活中，更好地运用。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477277080000,"updated_at":1477292444000,"ria":true},{"id":949,"topic":"化整为零，把大任务干掉。","learn_goal":"顺利通过1-2","remark":"你是不是一直想减肥，却苦于坚持不下去？\r\n你是不是好不容易坚持几天不抽烟，却在别人给你一根烟时前功尽弃？\r\n本周拆书家，带你学习《从行动开始》这本书，让你真正从行动开始，戒掉坏习惯，做成自己想做的事，在自我管理这条路上越走越顺！","level":"TF1-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"我叫徐佳敏，我喜欢不断探索，不断挖掘自己的潜能！今天我跟大家分享的书籍是《从行动开始》这本书，这本书的作者是石田淳，他是研究日本行为科学管理第一人，他在本书中反复强调能够导出结果的只有“行动”，而非意志，也就是说我们常说的意志力薄弱，我办不到，是不恰当的，那是给自己贴标签，是由错误的思维导致的。能够真正导出结果的只有行动，即使意志力薄弱也能办成事。就像我们平常比如跑步，我们一般坚持三天就跑不动了，我们就会给自己贴标签说“我意志力薄弱”“我办不到”，作者反对这样的观点。同时作者在书中介绍的“行动科学管理术”，启发我们重新审视自己的认知和行动目标，掌握行动的基本法则，更有效地规划自己的生活。这也是一本对我启发很大的书，推荐给大家。","ratings_count":0,"texts":[{"id":2891,"quote":null,"explains":"\u003cp>&nbsp; &nbsp; &nbsp; 片段大致讲述了分解大任务的重要性，过去，我们在面对庞大的事物时，往往首先被这个大任务给吓到了，先是让自己增添了许多压力，那我们学习了化整为零的方法后，就知道在遇到大任务时，我们首先要把它分解为许多可以完成的小任务，每天只需要完成当天的任务就好，带来的成就感也能促进我们每天坚持。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;那刚好我最近在看《悲惨世界》这本大部头，大概有1000多页，每一页都是密密麻麻的小字，如果一下子告诉自己，我要赶紧看完这本书，我想我估计到半个月都没怎么进展吧，学到了这个方法，我就告诉自己，1000页的话，那我每天读100页，我读书的速度慢，那我早上早起读个50页，然后中午吃完饭读25页，晚上睡前再读25页，这样一分解，其实就很简单了，差不多10天我就可以轻轻松松读完这本书。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;同样就是我1-1分享时讲到的8月份的那个分享，我有一个月的准备时间，我要快速学习的东西很多，我会觉得无从下手，那我把任务分解，大致要学哪几类知识，每一类知识要学习哪些具体东西，我把我分解后要学的东西分配到具体的每一天，那这样做起任务来其实就很轻松了。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>那通过这个片段的学习以及我自己两个的案例分享，相信大家应该对我们涉及的知识有了更清晰的理解，那大家可以回想一下你过去在工作，生活或学习中有没有遇到过面对大任务无法下手感觉有很大压力的事情，给大家5分钟的时间，请在小组内分享，然后我们请一两个小伙伴跟大家分享出来自己的具体情况。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>玉：我分享下暑期拆书的经历，刚开始拆主要拆实用类的，我是用思维导图的形式把它拆解出来，因为它是章节式的，内容比较少，刚开始我想怎么样让自己不要一次拆很多，而是先形成一个习惯，我发现有一个方法特别好用，就是一天只拆一章，只做一张思维导图，当你形成一个思维定势之后，你就会想着，欸，我今天是不是有什么事没做，就是把把大的分成小的，让小的形成习惯，你就会很自然地坚持下去。\u003c/p>\u003cp>A2：王玉同学的分享很棒，那今天，我们学习了如何面对大任务时“化整为零”，把大任务拆分为小任务，现在，请大家拿出便签纸，写下自己的A2便签，自己未来在学习，工作或者生活中遇到这种情况时该怎么化整为零，怎么分解，要具体可量化到每一天或者每个阶段。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474513641000,"updated_at":1474513641000},{"id":948,"topic":"正视事实，摆脱认知偏差。","learn_goal":"顺利通过1-1","remark":"你是不是在做不到某些事的时候告诉自己，我很笨，我意志力薄弱，我办不到？\r\n你是不是在面对大任务时手足无措，不知道怎么下手，只有满脑子的压力？\r\n你的朋友在街上没有跟你打招呼，你是不是觉得对方讨厌你，认为自己是不是哪里得罪他了？","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫徐佳敏，大家可以叫我佳敏或佳儿，我现在是一名研究生二年级的学生，工科专业，爱好文学。平常喜欢读书，喜欢把自己沉浸在书中的世界；喜欢旅行，喜欢在路上看不一样的风景；喜欢发呆，喜欢就那样静静地坐一下午；也喜欢码字，没事儿会写些生活感悟。向往诗与远方，也享受眼前的美好。因为我以前更倾向于文学类的书，很少看致用类的，也不怎么会把学到的知识真正用到生活中，所以希望通过拆书帮的学习方法帮助自己真正学以致用。","ratings_count":0,"texts":[{"id":2890,"quote":null,"explains":"\u003cp>原文片段讲述了“认知偏差”带来的负面影响，我们产生压力的途径并不是发生事情之后立即产生的压力，而是事情发生后经过我们大脑的认知偏差才引发的压力，也就是说事实上我们大脑让它拐了个弯。我们在面对事情发生时，习惯自己由事实联想到其他，产生很多不好的情绪，进而增添了自己的压力。那如何改善呢，片段中告诉我们一个简单直接的办法，就是正确认识发生的事情，发生了就去解决就好了，因为导致压力的因素是个人认知而非所发生的事情，所以发生事情后我们不要往里面加入自己带有偏见的认知，不要徒增自己的压力。\u003c/p>","interaction":"\u003cp>激活经验：8月份我在准备线上分享的时候，我把准备的东西拿给老师看，老师点评之后，说我辅导你的过程我都能写篇文章了，当时我其实很失落，觉得自己好笨，认为老师是不是后悔让我做分享了，准备了这么久还不能达到老师的要求，想想分享的时间快要临近了，越发感觉压力很大。其实老师也是真的为我好，要让我好好准备，分享的东西真正有用，那如果我正确面对这个事实，然后好好去准备就好了。\u003c/p>\u003cp>催化作用：学习了原文片段中简单直接的办法后，那这个A2我已经做过了，在写完这个便签的第二天我把翻译好的文章交给老师， 老师委婉地说我翻译的不够好，还有很多语法错误，那这时候，我就记着片段中学到的方法。那我首先就正视这个事实就好了，事实是我做的不够好，然后直接行动，努力再去好好改就行了，而不是听到老师批评就产生自我的认知偏差，认为“我好笨”，“我怎么老是做不好”“为什么学了这么多年英语还是学不好”之类的负面情绪。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474512758000,"updated_at":1474512758000}]};